as":[{"o":["Tadeu","Simão","Baltasar"],"c":1},{"o":["Camilo","Eça","Filippe Moreira Dias"],"c":0}],"f":"Simão é personagem; Camilo é o autor, «Na cadêa da Relação do Porto, aos 26 de Setembro de 1861».","_l":"m5-f09"},{"t":"vf","p":"Como Camilo esteve preso na mesma cadeia, a história de Simão é a história do autor.","v":false,"f":"Falso: é sugestão biográfica, não biografia; o autor escreveu preso, a personagem é ficção.","_l":"m5-f09"},{"t":"ordenar","p":"Como se preenche o caderno de campo, por ordem:","passos":["Observa tamanhos, luz, materiais","Escreve a lápis o que vês","No fim, liga ao romance ou ao autor"],"f":"Primeiro observar e registar; só no fim da visita interpretar.","_l":"m5-f09"},{"t":"completar","p":"O que leva cada coluna do caderno de campo?","frase":"A coluna «O que vi» pede [1] e a coluna da ligação pede [2] no fim da visita.","lacunas":[{"o":["observações concretas","opiniões pessoais","resumos do romance"],"c":0},{"o":["a frase do guia, copiada","ligações à obra ou ao autor","a data e a hora da visita"],"c":1}],"f":"Observações concretas; depois ligações pertinentes: o assento, as grades, a escrita na prisão.","_l":"m5-f09"},{"t":"escolha","p":"«Casa-museu reconstituída» quer dizer uma casa…","o":["refeita como era, para se visitar","mantida fechada, sem receber visitas","construída de novo, longe do lugar original","transformada em cadeia ou em tribunal"],"c":0,"f":"Reconstituída: refeita como era no tempo do escritor; hoje visita-se como museu.","_l":"m5-f09","fe":[null,"Uma casa-museu abre-se a quem a visita: reconstituída quer dizer refeita como era no tempo do escritor.","Reconstituir é refazer como era, não construir outra casa noutro sítio; a Casa de Camilo continua em Seide.","Quem passou de cadeia a museu foi o edifício do Porto; a Casa de Camilo é a casa do escritor, refeita como era."]},{"t":"escolha","p":"Onde fica a antiga cadeia, segundo a lição?","o":["Na rua de S. Francisco de Paula, nas Janelas Verdes","Na estrada de Saint-Cloud, perto de Paris","No Largo Amor de Perdição, junto à Torre dos Clérigos"],"c":2,"f":"Largo Amor de Perdição, com o nome do romance, junto à Torre dos Clérigos.","_l":"m5-f09"},{"t":"emparelhar","p":"Liga cada nome ao que a lição diz dele.","pares":[["Simão","preso na cadeia, no romance"],["Camilo","datou aí a dedicatória, em 1861"],["Largo Amor de Perdição","junto à Torre dos Clérigos"],["Vila Nova de Famalicão","concelho da Casa de Camilo"]],"f":"Simão preso na ficção, Camilo preso em 1861; o largo junto aos Clérigos; a casa em Famalicão.","_l":"m5-f09"},{"t":"escolha","voc":true,"p":"Em que cidade fica a antiga Cadeia da Relação, hoje Centro Português de Fotografia?","o":["Porto","Lisboa","Viseu"],"c":0,"f":"Porto: a Cadeia da Relação, onde Simão esteve preso e Camilo datou a dedicatória.","_l":"m5-f09"},{"t":"escolha","voc":true,"p":"Com que instrumento escreves no caderno de campo, no sítio?","o":["lápis","caneta","telemóvel"],"c":0,"f":"A lápis, no sítio, sem telemóvel: o caderno de campo enche-se durante a visita.","_l":"m5-f09"},{"t":"completar","voc":true,"p":"Entre que sinais copias a frase do guia, tal como a ouviste?","frase":"A frase do guia copia-se tal como a ouviste, entre [1].","lacunas":[{"o":["aspas","parênteses","vírgulas"],"c":0}],"f":"Entre aspas: a frase do guia copia-se tal como a ouviste, palavra por palavra.","_l":"m5-f09"},{"t":"emparelhar","p":"Liga cada coluna do caderno de campo ao que leva.","pares":[["Observar","um espaço, uma fotografia, um objeto, uma frase"],["O que vi","tamanhos, luz, materiais, a lápis"],["Ligação ao romance ou ao autor","fica para o fim da visita"]],"f":"Observar diz o que olhar; «O que vi» regista o concreto; a ligação escreve-se no fim.","_l":"m5-f09"},{"t":"emparelhar","p":"Liga cada lugar ou recurso ao que é.","pares":[["Centro Português de Fotografia","a antiga Cadeia da Relação"],["Casa-museu de Seide","onde o escritor viveu"],["Páginas dos dois museus","a visita de quem não pode ir"]],"f":"A antiga cadeia é o Centro de Fotografia; a casa de Seide é a do escritor; quem não vai visita online.","_l":"m5-f09"},{"t":"escolha","p":"Que dado da visita leva sempre fonte (guia, painel ou documento), para não confundir o autor com a personagem?","o":["O dado da vida de Camilo que ajuda a ler","O pormenor da cela que te mudou a leitura","O tamanho de uma cela, visto por ti no sítio","A fotografia que escolheste na exposição"],"c":0,"f":"O dado biográfico de Camilo leva fonte, para não confundir autor e personagem.","_l":"m5-f09","fe":[null,"O pormenor é observação tua, registada a lápis na coluna «O que vi»; o que leva fonte é o dado da vida de Camilo.","O tamanho de uma cela vês tu, no sítio: é observação. A fonte serve o dado biográfico, para não confundir autor e personagem.","A fotografia escolhes tu; a fonte (guia, painel ou documento) vai com o dado da vida de Camilo."]},{"t":"completar","p":"A que passos do romance ligas o que viste?","frase":"Liga o pormenor que viste a um passo do romance: o [1] ou os [2] de Simão.","lacunas":[{"o":["assento da cadeia","painel de azulejos","jantar do hotel"],"c":0},{"o":["dois anos","dezoito anos","dez anos"],"c":1}],"f":"O assento da cadeia e os dezoito anos de Simão: os passos a que ligas o que viste.","_l":"m5-f09"},{"t":"escolha","p":"Em que data saiu do Porto a nau que leva Simão?","o":["A 17 de março de 1807","A 26 de setembro de 1861","Num domingo de junho de 1803","A 28 de dezembro de 1815"],"c":0,"f":"A nau saiu do Porto a 17 de março de 1807, a data escrita à margem do assento.","_l":"m5-f08","fe":[null,"26 de setembro de 1861 é a data da dedicatória de Camilo; a nau de Simão sai do Porto a 17 de março de 1807, como diz a abertura da lição.","Num domingo de junho de 1803 Tadeu manda Teresa casar com Baltasar; a nau só sai quatro anos depois, a 17 de março de 1807.","Esta data não pertence ao romance: a nau de Simão sai do Porto a 17 de março de 1807, como diz a abertura da lição."]},{"t":"completar","p":"Que factos do romance tem Simão presentes nesta noite?","frase":"Simão vai [1] para a Índia por ter matado [2] e leva a bordo Mariana, a filha do ferrador.","lacunas":[{"o":["degredado","de visita","como soldado"],"c":0},{"o":["Tadeu","Baltasar","Domingos Botelho"],"c":1}],"f":"Degredado para a Índia por ter matado Baltasar; Mariana, a filha do ferrador, acompanha-o.","_l":"m5-f08"},{"t":"escolha","p":"Que perguntas deixou Teresa por responder?","o":["Se podia com a desesperança e se amaria outra vez","Se a perdoava por ter morrido e se voltaria a Viseu","Se ia escrever a Tadeu e se pensava fugir da nau","Se levava consigo a trança e se rezaria por ela"],"c":0,"f":"«Podias tu com a desesperança e com a vida?»; «Nunca hás de amar outra vez?».","_l":"m5-f08","fe":[null,"Teresa não pede perdão nem fala de Viseu: pergunta «podias tu com a desesperança e com a vida?» e «Nunca hás de amar outra vez?».","Tadeu e a fuga não estão nas perguntas finais; Teresa quer saber se Simão aguenta a «desesperança» e se voltará a amar.","A trança e as rezas não entram nas perguntas que a lição recorda; Teresa pergunta pela «desesperança» e por um amor futuro."]},{"t":"completar","p":"Que marcas tem de ter a carta?","frase":"Antes do vocativo, a carta leva [1]; depois do texto, leva uma [2] e a assinatura.","lacunas":[{"o":["título e resumo","local e data","tese e argumentos"],"c":1},{"o":["conclusão","refutação","despedida"],"c":2}],"f":"Local e data, vocativo, despedida, assinatura: as quatro marcas da carta.","_l":"m5-f08"},{"t":"vf","p":"Simão escreve a resposta na nau, na noite a seguir à morte de Teresa no convento de Monchique.","v":true,"f":"Verdadeiro: Teresa morreu no convento de Monchique; Simão responde «no alto mar», como ela pediu.","_l":"m5-f08"},{"t":"ordenar","p":"Como se escreve a carta, por ordem:","passos":["Relê a carta e sublinha as perguntas","Escreve três aberturas e escolhe uma","Faz o rascunho e risca por cima","Verifica datas e factos do romance"],"f":"O processo da lição: ler, abrir, rascunhar, verificar.","_l":"m5-f08"},{"t":"escolha","p":"Exemplo inventado: «Teresa, a tua ausência é um mar sem margem.» Que fazem os recursos nesta frase?","o":["Dirigem a fala a Teresa e dão uma imagem à ausência que Simão sente.","Relatam uma resposta de Teresa e descrevem o percurso real da nau.","Apresentam a voz do narrador e antecipam o regresso de Simão a Viseu.","Comprovam que Simão esqueceu Teresa e decidiu amar Mariana."],"c":0,"f":"**«Teresa»** é uma apóstrofe; **«mar sem margem»** é uma metáfora da ausência. Os recursos exprimem a relação e a dor; não servem apenas para cumprir uma lista. Podes construir outras imagens, desde que as consigas justificar.","_l":"m5-f08","fe":[null,"A frase é de Simão para Teresa, não uma resposta dela. «Mar sem margem» transforma a ausência numa imagem; não descreve um trajeto.","O vocativo dirige a fala a Teresa. A imagem não anuncia um regresso: Simão vai degredado para a Índia.","A «tua ausência» mostra a ligação a Teresa. A frase não permite concluir que Simão a esqueceu ou que ama Mariana."],"p2":"Exemplo inventado: «Teresa, a tua ausência é um mar sem margem.» Como ligam a apóstrofe e a metáfora esta frase à situação de Simão?","g":"fim"},{"t":"completar","p":"Quantas palavras tem a carta e o que é a «desesperança» de que Teresa fala?","frase":"A carta tem [1] palavras e responde à pergunta de Teresa sobre a «desesperança», que é a [2] diante da vida.","lacunas":[{"o":["220 a 300","50 a 80","500 a 600","10 a 20"],"c":0},{"o":["falta de esperança","falta de coragem","falta de memória","falta de amor"],"c":0}],"f":"220 a 300 palavras; «desesperança» é falta de esperança: Teresa pergunta se Simão pode com ela.","_l":"m5-f08"},{"t":"emparelhar","p":"Liga cada parte da carta ao que tem de ter.","pares":[["Local e data","a nau, 17 de março de 1807, noite"],["Vocativo e abertura","resposta direta à carta de Teresa"],["Memória","um episódio recordado"],["Futuro","o que Simão fará da vida"]],"f":"Local e data na nau; vocativo e abertura; uma memória; o futuro de Simão: o plano da carta.","_l":"m5-f08"},{"t":"escolha","voc":true,"p":"Como se chama a filha do ferrador que vai a bordo com Simão?","o":["Mariana","Teresa","Constança"],"c":0,"f":"Mariana, a filha do ferrador, embarca com Simão na nau para a Índia.","_l":"m5-f08"},{"t":"sublinhar","p":"Toca nas duas palavras que dizem onde Simão há de responder.","frase":"estas derradeiras perguntas, a que tu responderás, no alto mar","certas":[8,9],"f":"«No alto mar»: Simão responde na nau, a caminho da Índia.","_l":"m5-f08"},{"t":"vf","p":"Antes de reler. Nas cartas do romance, aquilo que se escreve coincide com o que o destinatário chega a conhecer?","v":false,"f":"Confundir intenção comunicativa e receção elimina os obstáculos do contacto. Relê a situação das cartas na F04 e distingue quem escreve, a quem se dirige e o que fica conhecido.","_l":"m5-f17"},{"t":"escolha","p":"Que informação altera a explicação do silêncio?","o":["O pai mandava retirar as cartas no correio.","A mãe mandava retirar as suas cartas no correio.","Simão mandava retirar as cartas no correio."],"c":0,"f":"A descoberta das cartas revela uma interferência no canal. A falta de resposta deixa de poder ser atribuída automaticamente a uma decisão de Simão.","fe":["A descoberta das cartas revela uma interferência no canal. A falta de resposta deixa de poder ser atribuída automaticamente a uma decisão de Simão.","Trocas quem ordena a interceção por quem espera resposta. Relê a informação sobre o pai e o correio.","Atribuis ao destinatário a ordem de interceptar as cartas. Relê quem as fazia retirar e quem permanece sem essa informação."],"_l":"m5-f17"}],"licoes":["m5-f02","m5-f04","m5-f17","m5-f07","m5-f09","m5-f08"]},{"n":2,"titulo":"A casa dos Maias","passos":[{"id":"m5-f10","licao":"m5-f10","exs":[],"ativ":["ler","eca-ramalhete"]},{"id":"m5-f16","licao":"m5-f16","exs":[],"ativ":["ler"]},{"id":"m5-f11","licao":"m5-f11","exs":[],"ativ":["ler","eca-hotel"]},{"id":"m5-f12","licao":"m5-f12","exs":[],"ativ":["ler","gram-dil"]},{"id":"m5-f14","licao":"m5-f14","exs":[],"ativ":["ler"]},{"id":"m5-f13","licao":"m5-f13","exs":[],"ativ":["ler","eca-falhamos"]},{"id":"m5-o-pais-ou-eles","licao":null,"exs":["m5-o-pais-ou-eles"]},{"id":"m5-f15","licao":"m5-f15","exs":[],"ativ":["ler"]}],"emblema":"data:image/jpeg;base64,","simbolo":"<svg class=\"simbolo\" viewBox=\"0 0 48 48\" aria-hidden=\"true\" data-ico=\"monoculo\"><circle cx=\"22\" cy=\"22\" r=\"12\"/><circle cx=\"22\" cy=\"22\" r=\"8\"/><path d=\"M31 31l9 9\"/><path d=\"M34 40c2 2 6 2 6-2\"/></svg>","pool":[{"t":"completar","p":"Quando chegam os Maias e onde fica o Ramalhete?","frase":"Os Maias chegam ao Ramalhete no outono de [1]; a casa fica em [2] e é conhecida no bairro das Janelas Verdes.","lacunas":[{"o":["1858","1875","1888"],"c":1},{"o":["Porto","Sintra","Lisboa"],"c":2}],"f":"«no outono de 1875», em Lisboa; 1858 é a visita do Núncio, 1888 a data do romance.","p2":"Em que ano vêm os Maias viver para o Ramalhete, e em que cidade fica a casa?","_l":"m5-f10"},{"t":"escolha","p":"Quem murmura «Só vivi dois annos n'esta casa»?","o":["Ega, ao Carlos, no sofá","Carlos, ao Ega, na rua","Villaça, ao Núncio, no quintal"],"c":1,"f":"Carlos, «travando do braço do Ega», ao dar o último olhar ao casarão.","_l":"m5-f10"},{"t":"escolha","p":"De onde vem o nome «Ramalhete»?","o":["De um painel de azulejos com um ramo de girassóis","De um brasão de armas com flores, no topo da fachada","De um quintal com cipreste, cedro e uma cascata","De uma cruz e de uma sineta no alto do telhado"],"c":0,"f":"Azulejos com «um grande ramo de girasoes», no lugar do brasão «que nunca chegara a ser collocado».","_l":"m5-f10","fe":[null,"O brasão «nunca chegara a ser collocado»: no lugar dele está o painel de azulejos com «um grande ramo de girasoes».","O quintal é «pobre» e «inculto», com cipreste e cedro, sem flores; o nome vem do painel de girassóis na fachada.","A cruz e a sineta não existem: o narrador diz que, com elas, a casa pareceria «um Collegio de Jesuitas». O nome vem dos azulejos."]},{"t":"completar","p":"Que expressões voltam no fim e o que mudou?","frase":"No fim voltam «sombrio casarão» e [1] do início; as «janellinhas», antes «timida fila», estão agora [2] e em penumbra.","lacunas":[{"o":["«ramo de girasoes»","«tons de ruina»","«paz dormente»"],"c":1},{"o":["«abrigadas»","«estreitas»","«fechadas»"],"c":2}],"f":"Repetem-se «tons de ruina»; as janelinhas ficam «fechadas»: as mesmas palavras, agravadas até «para sempre deshabitado».","_l":"m5-f10"},{"t":"escolha","p":"Abrir e fechar o romance com a mesma descrição chama-se…","o":["estrutura circular","analepse (recuo no tempo)","prolepse (avanço no tempo)","sugestão biográfica"],"c":0,"f":"Estrutura circular: a história volta ao ponto de partida, mas pior.","_l":"m5-f10","fe":[null,"A analepse recua no tempo a meio da história; aqui o romance acaba onde começou, com a mesma descrição do Ramalhete.","A prolepse antecipa o que vai acontecer; repetir no fim as palavras do início («sombrio casarão») fecha um círculo.","Sugestão biográfica é ligar a obra à vida do autor, como Camilo na cadeia; aqui fala-se da forma do romance."]},{"t":"vf","p":"O quintal do Ramalhete é um jardim de luxo, com arvoredos e águas, como o Núncio queria.","v":false,"f":"Falso: «um pobre quintal inculto», com cipreste, cascata seca, tanque entulhado e Vénus a enegrecer.","_l":"m5-f10"},{"t":"escolha","p":"Que anunciam a Vénus a enegrecer e o cipreste no quintal?","o":["Amor e morte: a paixão e a ruína que virão","Riqueza e fé: a nobreza dos Maias e a Igreja","Campo e frescura: a vida de uma vivenda campestre","Ordem e trabalho: um quintal bem tratado"],"c":0,"f":"Vénus é a deusa do amor, o cipreste a árvore dos cemitérios: o espaço anuncia a tragédia.","_l":"m5-f10","fe":[null,"A Igreja está no aspeto da casa («Residencia Ecclesiastica»), não no quintal; Vénus é a deusa do amor e o cipreste, a árvore dos cemitérios.","O «fresco nome de vivenda campestre» engana: o quintal é «inculto», e a Vénus está a enegrecer junto a um cipreste.","O quintal está «abandonado ás hervas bravas», com um tanque entulhado: nada ali é ordem. Vénus e o cipreste falam de amor e de morte."]},{"t":"completar","p":"Que querem dizer «Residencia Ecclesiastica» e «Nuncio»?","frase":"«Residencia Ecclesiastica» é uma [1] e «Nuncio» é o [2] que visitou a casa em 1858.","lacunas":[{"o":["casa de padres","casa de nobres","casa de campo"],"c":0},{"o":["administrador dos Maias","embaixador do Papa","procurador do rei"],"c":1}],"f":"Casa de padres; embaixador do Papa: o Núncio Buccarini visitou-a em 1858 e não ficou.","_l":"m5-f10"},{"t":"sublinhar","p":"Toca nas duas palavras que o fim acrescenta: a escuridão e o abandono.","frase":"as grades dos postigos terreos cheias de treva, mudo, para sempre deshabitado,","certas":[7,11],"f":"«Treva» e «deshabitado»: o fim agrava o início com escuridão e abandono definitivo.","_l":"m5-f10"},{"t":"versos","p":"Põe as frases do fim do romance pela ordem do texto B.","linhas":["Depois na rua Carlos parou, deu um longo olhar ao sombrio casarão,","Uma commoção passou-lhe n'alma, murmurou, travando do braço do Ega:","— É curioso! Só vivi dois annos n'esta casa,","Ega não se admirava."],"f":"Carlos olha a casa, comove-se, fala ao Ega; Ega não se admira: é a ordem do fim.","_l":"m5-f10"},{"t":"escolha","voc":true,"p":"Que palavra do texto A quer dizer «fila»?","o":["renque","painel","postigo"],"c":0,"f":"«Um renque de estreitas varandas de ferro»: renque é fila.","_l":"m5-f10"},{"t":"escolha","p":"Quem janta no Hotel Central, no capítulo VI?","o":["Ega, Carlos, Villaça, Afonso e Dâmaso","Ega, Alencar, Craft, Carlos e Cohen","Alencar, Craft, Cohen, Afonso e Villaça"],"c":1,"f":"Cinco à mesa: Ega, Alencar, Craft, Carlos e Cohen, mais o criado com o linguado.","_l":"m5-f11"},{"t":"completar","p":"O que recusa Alencar à hora do jantar?","frase":"Alencar condena o realismo por [1] e manda não discutir «[2]» à hora do jantar.","lacunas":[{"o":["pouco científico","demasiado belo","imoral"],"c":2},{"o":["o excremento","a forma","o imposto"],"c":0}],"f":"«Não discutamos o excremento»: para Alencar é «litteratura latrinaria», de esgoto.","_l":"m5-f11"},{"t":"completar","p":"Que posições defendem Craft e Ega?","frase":"Para Craft, «a arte era uma [1]»; para Ega, o realismo era ainda «pouco [2]» e devia ser monografia.","lacunas":[{"o":["monographia","phantasia","idealisação"],"c":2},{"o":["pittoresco","scientifico","moral"],"c":1}],"f":"Craft: «A arte era uma idealisação!»; Ega: «ainda pouco scientifico», quer a monografia seca.","_l":"m5-f11"},{"t":"escolha","p":"Quem diz «A banca-rota é inevitavel: é como quem faz uma somma»?","o":["Cohen, a sorrir, com uma pitada de sal","Carlos, que confessa não entender de finanças","Ega, de cotovelos fincados na mesa, a ouvir","Alencar, com a mão no nariz e água de colónia"],"c":0,"f":"Cohen anuncia a falência do país «sorrindo»: a ruína como cálculo.","_l":"m5-f11","fe":[null,"Carlos só acha que o país ia «alegremente e lindamente» para a bancarrota; a frase da soma é a resposta de Cohen, «sorrindo».","Ega ouve, não fala: finca os cotovelos «para lhe beber melhor as palavras». Quem diz a frase é Cohen.","A mão no nariz é a crítica de Alencar ao realismo, mais cedo no jantar; a frase da soma é de Cohen (parágrafo 15)."]},{"t":"escolha","p":"Que efeito tem o «Sole normande?» do criado?","o":["Ironia: o prato corta a discussão elevada","Suspense: deixa por saber a resposta de Cohen","Comoção: prepara uma leitura sentimental da cena","Revolta: os convivas zangam-se com o criado"],"c":0,"f":"Ironia: o jantar vale mais do que as ideias; o prato francês mostra ainda o estrangeirismo da elite.","_l":"m5-f11","fe":[null,"A pergunta a Cohen só vem depois (parágrafo 11); o «Sole normande?» interrompe o debate sobre o realismo.","Comover a leitora é coisa do narrador de Camilo; aqui o prato cai no meio das «philosophias» e faz sorrir.","Ninguém se zanga: o criado oferece o linguado e a conversa elevada fica cortada a meio, com ironia."]},{"t":"completar","p":"Que distingue o realismo do naturalismo?","frase":"O realismo mostra a sociedade [1]; o naturalismo estuda as pessoas [2] e explica-as pelo meio.","lacunas":[{"o":["como devia ser, idealizada","como a sonha o poeta","como ela é, sem a embelezar"],"c":2},{"o":["como um médico estuda um caso","como um padre ouve uma confissão","como um juiz julga um réu"],"c":0}],"f":"Realismo sem embelezar; naturalismo clínico, pelo meio e pela hereditariedade, com Zola como mestre.","_l":"m5-f11"},{"t":"vf","p":"Carlos ataca o realismo porque o acha imoral, como Alencar.","v":false,"f":"Falso: Carlos recusa «os seus grandes ares scientificos», a pose de ciência; a imoralidade é a razão de Alencar.","_l":"m5-f11"},{"t":"escolha","p":"«Vocês estão gastando cêra com ruins defuntos» quer dizer…","o":["perder tempo com o que não merece","gastar dinheiro com funerais","acender velas pelos mortos"],"c":0,"f":"Glossário: perder tempo com o que não merece; Alencar despacha a discussão com «mão no nariz!».","_l":"m5-f11"},{"t":"sublinhar","p":"Toca nas duas palavras que tornam irónica a ida do país para a falência.","frase":"o paiz ia alegremente e lindamente para a banca-rota.","certas":[3,5],"f":"«Alegremente» e «lindamente»: a ruína descrita como uma festa; é a ironia de Eça.","_l":"m5-f11"},{"t":"emparelhar","p":"Liga cada personagem ao que recusa ou defende no debate.","pares":[["Alencar","a imoralidade: «excremento»"],["Craft","a fealdade: a arte idealiza"],["Carlos","os ares científicos do realismo"],["Ega","quer o realismo ainda mais científico"]],"f":"Alencar recusa a imoralidade, Craft a fealdade, Carlos a pose científica; Ega quer mais ciência.","_l":"m5-f11"},{"t":"versos","p":"Põe os momentos do jantar pela ordem do texto.","linhas":["Isto levou logo a fallar-se do Assommoir, de Zola e do realismo:","— Isso é absurdo, dizia Carlos, os caracteres só se podem manifestar pela acção...","— Sole normande? perguntou-lhe o creado, adiantando a travessa.","O emprestimo faz-se ou não se faz?"],"f":"Zola, a discussão, o linguado do criado e, por fim, o empréstimo: a conversa muda de assunto.","_l":"m5-f11"},{"t":"completar","p":"Que marcas têm o discurso direto e o indireto?","frase":"O discurso direto reproduz as palavras com [1]; o indireto relata com [2] e subordinação.","lacunas":[{"o":["verbo declarativo","imperfeito","travessão ou aspas"],"c":2},{"o":["travessão ou aspas","verbo declarativo","exclamações"],"c":1}],"f":"Direto com travessão ou aspas («—Não!»); indireto com verbo declarativo e subordinação («Carlos disse que não»).","_l":"m5-f12"},{"t":"escolha","p":"No indireto livre, a voz da personagem entra na do narrador…","o":["sem verbo declarativo nem travessão","com verbo declarativo e com travessão","com aspas e sempre na primeira pessoa","com um verbo declarativo e aspas"],"c":0,"f":"Sem verbo declarativo nem travessão: mantém exclamações, interrogações e expressões da personagem, na 3.ª pessoa e no imperfeito.","p2":"Como entra a voz da personagem na do narrador, no indireto livre?","_l":"m5-f12","fe":[null,"Verbo declarativo e travessão são marcas do direto; no indireto livre não há «disse» nem travessão, como em «Olha que brincadeira, hein!».","As aspas e a 1.ª pessoa são do discurso direto; no indireto livre a voz da personagem entra na narração sem marca.","Com verbo declarativo e aspas a fala fica separada; no indireto livre não há separação, como em «Pois bem.»."]},{"t":"escolha","p":"De quem é a voz em «Para que? Para arrastar os passos tristes desde o Gremio…»?","o":["De Ega, que lhe propõe voltar","De Alencar, que defende a Moral","De Carlos, que não quer voltar"],"c":2,"f":"Carlos «considerou Ega com espanto»: as interrogações e o «Não!» são dele, sem travessão.","_l":"m5-f12"},{"t":"completar","p":"Que marcas de indireto livre há na passagem de Alencar e de quem é a voz?","frase":"Em «Elle, Alencar, seria o paladino da Moral», há [1] e condicional «seria»: a voz é de [2] a pensar em si.","lacunas":[{"o":["1.ª pessoa","2.ª pessoa","3.ª pessoa"],"c":2},{"o":["Alencar","Ega","Carlos"],"c":0}],"f":"3.ª pessoa e condicional: o narrador imita Alencar a falar de si, «paladino da Moral, gendarme dos bons costumes».","_l":"m5-f12"},{"t":"completar","p":"Que marca tem «Olha que brincadeira, hein!» e de quem é a voz?","frase":"Em «Olha que brincadeira, hein!», a marca é a expressão [1] e a voz é de [2] a ouvir Cohen.","lacunas":[{"o":["neutra e declarativa","coloquial e exclamativa","formal e interrogativa"],"c":1},{"o":["Carlos","Ega","Alencar"],"c":1}],"f":"Expressão coloquial e exclamativa de Ega, no meio da narração, sem travessão nem «disse».","_l":"m5-f12"},{"t":"ordenar","p":"Para passar a passagem de Carlos a discurso indireto, por ordem:","passos":["Escolhe um verbo que relate a intenção da personagem","Introduz o conteúdo com que ou se, conforme a intenção","Confere pessoa, tempo e deíticos no contexto do relato"],"f":"Escolhe um verbo adequado, como **perguntar** ou **afirmar**, e preserva o sentido. Depois verifica quem relata, quando e onde: ajusta as referências que o novo contexto exigir.","_l":"m5-f12","p2":"Para relatar a reação de Carlos em «Para que? […] Não!» através de uma oração subordinada, que passos segues?","g":"fim"},{"t":"vf","p":"O indireto livre afasta o leitor do pensamento da personagem.","v":false,"f":"Falso: aproxima o leitor do pensamento da personagem sem abandonar o narrador, e permite a ironia.","_l":"m5-f12"},{"t":"escolha","p":"«Paladino», em «paladino da Moral», quer dizer…","o":["juiz","defensor","inimigo"],"c":1,"f":"Glossário: paladino, defensor; «gendarme» é polícia, em francês.","_l":"m5-f12"},{"t":"sublinhar","p":"Toca na forma verbal que marca o indireto livre: condicional, na 3.ª pessoa.","frase":"Elle, Alencar, seria o paladino da Moral, o gendarme dos bons costumes.","certas":[2],"f":"«Seria»: condicional na 3.ª pessoa; é Alencar a pensar, na voz do narrador.","_l":"m5-f12"},{"t":"emparelhar","p":"Liga cada modo de relatar às suas marcas.","pares":[["Discurso direto","travessão ou aspas, palavras tal como foram ditas"],["Discurso indireto","verbo declarativo e subordinação"],["Discurso indireto livre","sem travessão nem verbo declarativo"]],"f":"Direto com travessão ou aspas; indireto com verbo declarativo; indireto livre sem nenhum dos dois.","_l":"m5-f12"},{"t":"escolha","voc":true,"p":"Que palavra francesa da passagem de Alencar quer dizer «polícia»?","o":["gendarme","paladino","congenere"],"c":0,"f":"«Gendarme dos bons costumes»: polícia, em francês; Alencar imagina-se guarda da Moral.","_l":"m5-f12"},{"t":"sublinhar","p":"Toca na palavra que responde à pergunta de Carlos, sem travessão nem verbo declarativo.","frase":"Para arrastar os passos tristes desde o Gremio até á Casa Havaneza? Não!","certas":[12],"f":"«Não!»: a resposta de Carlos entra na narração sem travessão; é indireto livre.","_l":"m5-f12"},{"t":"versos","p":"Põe as frases da passagem de Carlos e Ega pela ordem do texto.","linhas":["Então Ega perguntou, do fundo do sofá onde se enterrára,","Carlos considerou Ega com espanto.","Paris era o unico logar da terra congenere com o typo definitivo"],"f":"Ega pergunta, Carlos espanta-se, e a resposta vem em indireto livre: Paris.","_l":"m5-f12"},{"t":"escolha","voc":true,"p":"Que tipo de verbo tem o discurso indireto e não tem o indireto livre?","o":["Verbo declarativo","Verbo no imperfeito","Verbo no condicional"],"c":0,"f":"Verbo declarativo («disse que»): o indireto tem-no, o indireto livre dispensa-o.","_l":"m5-f12"},{"t":"escolha","p":"No indireto livre, em que pessoa e em que tempo fica a voz da personagem?","o":["Na 3.ª pessoa e no imperfeito","Na 1.ª pessoa e no presente","Na 2.ª pessoa e no futuro"],"c":0,"f":"Terceira pessoa e imperfeito: a personagem pensa, mas é o narrador que conjuga.","_l":"m5-f12"},{"t":"completar","p":"O que se acrescenta para passar a fala de Ega a direto e a indireto?","frase":"A passagem de Ega passa a direto com [1] e a indireto com [2] e sem exclamação.","lacunas":[{"o":["um travessão a abrir","um verbo declarativo","o pretérito imperfeito"],"c":0},{"o":["um travessão a abrir","um verbo declarativo","o pretérito imperfeito"],"c":1}],"f":"Direto: travessão; indireto: verbo declarativo, como «disse que». O indireto livre não tem nenhum.","_l":"m5-f12"},{"t":"vf","p":"O indireto livre mantém as exclamações e as interrogações da personagem.","v":true,"f":"Verdadeiro: ficam as exclamações e interrogações, mas na 3.ª pessoa e sem travessão.","_l":"m5-f12"},{"t":"escolha","p":"Quem escreveu e realizou _Os Maias: Cenas da Vida Romântica_?","o":["João Botelho","Jorge Vaz de Carvalho","Eça de Queirós","Carlos da Maia"],"c":0,"f":"Escrito e realizado por João Botelho; Jorge Vaz de Carvalho é a voz da narração.","_l":"m5-f14","fe":[null,"Jorge Vaz de Carvalho é a voz da narração, em voz _off_; o filme foi escrito e realizado por João Botelho.","Eça escreveu o romance, em 1888; o filme de 2014, que o adapta, é de João Botelho.","Carlos da Maia é a personagem principal do romance, não quem fez o filme; o realizador é João Botelho."]},{"t":"completar","p":"Quando estreou o filme, e em que formato passou depois na televisão?","p2":"Em que ano chegou o filme aos cinemas, e o que deu na televisão no ano seguinte?","frase":"O filme estreou nos cinemas em [1] e, no ano seguinte, passou na televisão como [2].","lacunas":[{"o":["2014","2015","1888","2016"],"c":0},{"o":["minissérie","telenovela","documentário","concurso"],"c":0}],"f":"Cinema em **2014**; em 2015, **minissérie** na RTP1 numa versão alargada com cenas inéditas. Identifica a versão e a marca temporal para que outra pessoa possa conferir o excerto.","g":"fim","_l":"m5-f14"},{"t":"escolha","p":"Que registo permite comprovar a presença de narração num excerto?","p2":"Que observação distingue uma voz narrativa dos outros elementos de um excerto?","o":["Ouve-se uma voz que conta ou descreve, para além do diálogo da cena","A imagem parece corresponder ao lugar descrito no romance","O plano demora bastante e tem poucas mudanças de câmara","Uma personagem repete uma expressão usada no romance"],"c":0,"f":"A **função da voz** é o indício: conta ou descreve. A duração do plano e a semelhança do cenário não provam narração; uma expressão do romance pode surgir no diálogo. Depois de identificar a voz, analisa como ela se relaciona com a imagem.","g":"fim","fe":[null,"O cenário permite comparar espaços, mas não comprova uma voz narrativa. É preciso registar o que se ouve.","Um plano demorado permite discutir ritmo; não comprova a presença de narração.","Uma personagem pode usar palavras do romance num diálogo. Isso, por si só, não prova uma voz narrativa exterior à cena."],"_l":"m5-f14"},{"t":"completar","p":"O que vai em cada coluna do guião?","p2":"Que se regista na coluna do ecrã, e que se diz na última coluna?","frase":"Na coluna «No ecrã» registas [1]; na coluna «Escolha e efeito» dizes [2] em cada momento.","lacunas":[{"o":["plano, luz, som, voz","a citação do livro","o resumo do capítulo","o nome do ator"],"c":0},{"o":["o efeito, com indícios","o que se vê e se ouve","quem realizou o filme","a data da estreia do filme"],"c":0}],"f":"**Plano, luz, som, voz** são observações; **o efeito, com indícios**, é uma interpretação a justificar. Regista versão e marca temporal. Não tens de inventar uma perda para equilibrar a resposta: explica o que consegues sustentar.","g":"fim","_l":"m5-f14"},{"t":"ordenar","p":"Como se preenche o guião de visionamento, por ordem:","p2":"Do livro ao juízo: que passos dás em cada momento do guião?","passos":["Relê o momento nos excertos e escolhe uma citação curta","Identifica a versão e localiza o excerto no ecrã","Regista plano, luz, som, voz e marca temporal","Relaciona a escolha com um efeito e testa o teu juízo"],"f":"Passagem do romance, excerto identificado, observação, juízo fundamentado. Se não consegues localizar um indício, limita ou revê a conclusão.","g":"fim","_l":"m5-f14"},{"t":"vf","p":"Uma adaptação só é boa se mostrar tudo o que está no livro.","v":false,"f":"Falso: adaptar é decidir, encurtar e mudar; cada escolha julga-se pelo que ganha e perde.","_l":"m5-f14"},{"t":"completar","p":"Que momentos do romance compara o guião?","frase":"O guião compara quatro momentos, do [1] ao final, passando pelo jantar no [2].","lacunas":[{"o":["Ramalhete","Grémio","Bignon","convento"],"c":0},{"o":["Hotel Central","Grémio","Bignon","Ramalhete"],"c":0}],"f":"Do **Ramalhete** ao final, passando pelo jantar no **Hotel Central**: momentos que já leste nas lições.","_l":"m5-f14"},{"t":"escolha","voc":true,"p":"Neste guião, o que designa «narração em voz _off_»?","p2":"Como reconheces a narração em voz off neste guião?","o":["uma voz narrativa ouvida sobre as imagens, sem ver quem a profere nesse plano","a voz de uma personagem em cena, que se vê a falar enquanto diz as suas palavras","a música que acompanha uma cena e lhe dá o tom, sem nenhuma palavra dita","o som ambiente de uma cena, como passos, vozes ao longe ou o vento na rua"],"c":0,"f":"Aqui, **narração em voz off** designa a voz que conta ou descreve sobre as imagens. Distingue-a do diálogo, da música e do som ambiente. Não concluas que produz sempre ironia ou lentidão.","g":"fim","_l":"m5-f14","fe":[null,"Se se vê quem fala, é diálogo: a voz _off_ ouve-se sobre as imagens sem que se veja quem a diz nesse plano.","A música não conta nem descreve; a narração em voz _off_ é uma voz que conta, como a de Jorge Vaz de Carvalho.","O som ambiente pertence à cena; a voz _off_ é uma voz narrativa por cima das imagens."]},{"t":"emparelhar","p":"Liga cada nome ao seu papel na adaptação.","pares":[["João Botelho","escreveu e realizou o filme"],["Jorge Vaz de Carvalho","diz a narração, na voz de Eça"],["_Cenas da Vida Romântica_","o subtítulo do filme"]],"f":"Botelho escreveu e realizou; Vaz de Carvalho narra; _Cenas da Vida Romântica_ é o subtítulo.","_l":"m5-f14"},{"t":"escolha","voc":true,"p":"Que palavra diz o que o filme é, em relação ao livro?","o":["adaptação","narração","minissérie"],"c":0,"f":"Adaptação: o filme toma decisões sobre o que mostra, que voz usa e o que fica de fora.","_l":"m5-f14"},{"t":"emparelhar","p":"Liga cada coluna do guião de visionamento ao que leva.","pares":[["Momento","o Ramalhete, o jantar, uma personagem-tipo, o final"],["No livro","excerto das lições, com citação curta"],["No ecrã","plano, luz, som, voz"],["Escolha e efeito","efeito proposto e indícios que o sustentam"]],"f":"Distingue passagem do romance, observação do ecrã e juízo. A versão e a marca temporal permitem conferir o excerto.","_l":"m5-f14"},{"t":"emparelhar","p":"Liga cada registo ao aspeto que permite analisar.","p2":"Que dimensão de análise corresponde a cada observação?","pares":[["A voz repete uma expressão do romance","Relação entre palavra escrita e palavra dita"],["O plano mantém-se durante uma pausa na narração","Relação entre duração, voz e montagem"],["A fachada ocupa todo o enquadramento","Seleção visual do espaço"]],"f":"Estes registos dão pontos de partida. A classificação não decide o efeito: uma pausa pode ter funções diferentes. Explica o que acontece naquele excerto antes de concluir que ganha ironia ou perde ritmo.","g":"fim","_l":"m5-f14"},{"t":"escolha","voc":true,"p":"Que nome tem a série de episódios que o filme originou, exibida pela RTP1?","o":["Minissérie","Adaptação","Guião"],"c":0,"f":"Minissérie: exibida pela RTP1 a 28 de dezembro de 2015, a partir do filme de 2014.","_l":"m5-f14"},{"t":"escolha","p":"Na pergunta final, o que pede a lição quando o filme encurtou ou mudou um momento?","o":["Dizer se foi boa decisão e porquê","Contar o momento como está no livro","Indicar quem realizou a cena"],"c":0,"f":"Pede um juízo: foi boa decisão, porque…; o momento identifica-se a partir das lições.","_l":"m5-f14"},{"t":"completar","p":"Quem indica os episódios e quem interpreta a narração?","frase":"Vês os episódios que o [1] indicar; a voz da narração é interpretada por [2].","lacunas":[{"o":["realizador","docente","narrador"],"c":1},{"o":["Vaz de Carvalho","João Botelho","Eça de Queirós"],"c":0}],"f":"O **docente** indica os episódios; **Jorge Vaz de Carvalho** interpreta a voz narrativa. Distingue o intérprete, o realizador e o autor do romance.","_l":"m5-f14"},{"t":"escolha","p":"Hipóteses inventadas: A mostra a fachada sem voz; B usa o mesmo plano com «sombrio casarão de paredes severas» e uma pausa. Que conclusão respeita o que sabemos?","p2":"Num exemplo inventado, A mostra a fachada sem voz; B acrescenta ao mesmo plano «sombrio casarão de paredes severas» e uma pausa. Que afirmação separa observação e interpretação?","o":["A versão B acrescenta a expressão e uma pausa; o efeito no ritmo exige observar a duração e a relação com a imagem","A versão B conserva palavras de Eça; por isso, conserva necessariamente toda a ironia do romance","A versão A não tem narrador; por isso, não pode construir nenhum juízo sobre a fachada","A versão B tem mais som; por isso, será sempre mais rápida do que a versão A"],"c":0,"f":"A primeira conclusão distingue o que foi **alterado** daquilo que ainda é preciso **testar**. O exemplo é inventado: nenhuma destas descrições comprova um plano real do filme.","g":"fim","fe":[null,"As mesmas palavras podem ter efeitos diferentes conforme a leitura, o contexto e a imagem. Não basta citar para provar ironia.","Imagem, enquadramento e montagem também podem orientar um juízo. A ausência de narração não elimina essa possibilidade.","Quantidade de som não equivale a velocidade. Compara duração, pausas e montagem."],"_l":"m5-f14"},{"t":"escolha","p":"Quem exclama «Falhámos a vida, menino!»?","o":["Ega, erguendo-se com um gesto desolado","Carlos, ao dar um longo olhar ao casarão","Afonso, do fundo do sofá onde se enterrara","Alencar, a calçar as luvas para sair"],"c":0,"f":"Ega «ergueu-se, atirou um gesto desolado» e disse a frase; Carlos responde «Creio que sim».","_l":"m5-f13","fe":[null,"Carlos responde à frase com «Creio que sim...»; o longo olhar ao casarão vem depois, já na rua (parágrafo 8).","Afonso não está nesta cena: no quarto só estão Carlos e Ega, e quem se enterrara no sofá era Ega.","Alencar não está no quarto; as luvas são calçadas depois da frase, «com um suspiro mudo» (parágrafo 7)."]},{"t":"completar","p":"Com que juízo fecha Carlos a lista de Paris?","frase":"Carlos fecha a lista com «Nada mais inoffensivo, mais nullo, e mais [1]»: vida cheia de coisas, [2] de sentido.","lacunas":[{"o":["elegante","agradavel","sincero"],"c":1},{"o":["vazia","cheia","rica"],"c":0}],"f":"«Nada mais inoffensivo, mais nullo, e mais agradavel»: uma vida cheia de coisas e vazia de sentido, em indireto livre.","_l":"m5-f13"},{"t":"completar","p":"Que diz Carlos da vida planeada e da vida real?","frase":"Segundo Carlos, planeia-se ser «assim» e é-se sempre «[1]» na realidade, às vezes [2] e sempre diferente.","lacunas":[{"o":["assado","outro","perfeito"],"c":0},{"o":["pior","melhor","igual"],"c":1}],"f":"«é-se invariavelmente assado», «Ás vezes melhor, mas sempre differente»: falha-se a vida planeada.","_l":"m5-f13"},{"t":"escolha","p":"Para Ega, ser «romantico» é governar-se na vida…","o":["pelo sentimento e não pela razão","pela razão e não pelo sentimento","pelo dinheiro e não pela arte","pela honra e não pelo amor"],"c":0,"f":"«individuos inferiores que se governam na vida pelo sentimento e não pela razão», desde o colégio.","_l":"m5-f13","fe":[null,"É ao contrário: Ega diz que os românticos se governam «pelo sentimento e não pela razão».","Dinheiro e arte não entram na definição de Ega (parágrafo 13): os românticos governam-se pelo sentimento.","Honra contra amor é o conflito de Camilo; Ega define os românticos pelo sentimento, contra a razão."]},{"t":"completar","p":"Que peças tem um texto de opinião?","frase":"Num texto de opinião, a [1] é a posição numa frase; a [2] é a resposta a quem discorda.","lacunas":[{"o":["modalização","tese","conclusão"],"c":1},{"o":["tese","modalização","refutação"],"c":2}],"f":"Tese, argumentos com exemplo, contra-argumento, refutação; a modalização marca o grau de certeza.","_l":"m5-f13"},{"t":"vf","p":"Para a crítica social, o texto de opinião pode juntar a este excerto o jantar do Hotel Central.","v":true,"f":"Verdadeiro: no Hotel Central, uma elite sabe que o país vai falir e muda de assunto; é um bom exemplo para a crítica social.","p2":"Ao excerto do balanço final pode juntar-se o jantar do Hotel Central, para a crítica social.","_l":"m5-f13"},{"t":"ordenar","p":"A estrutura do texto de opinião, por ordem:","passos":["Tese, numa frase","Dois argumentos com exemplos","Contra-argumento e refutação","Conclusão que volta à tese"],"f":"Da encomenda: tese, argumentos, contra-argumento e refutação, conclusão.","_l":"m5-f13"},{"t":"escolha","p":"Na lista de Carlos, «uma pouca de blague» é…","o":["esgrima","antiguidades","piada"],"c":2,"f":"Glossário: _blague_, piada, em francês; florete é esgrima e _bric-à-brac_ antiguidades.","_l":"m5-f13"},{"t":"versos","p":"Põe as falas do balanço final pela ordem do texto.","linhas":["— Falhámos a vida, menino!","— Creio que sim... Mas todo o mundo mais ou menos a falha.","Ega concordou, com um suspiro mudo, começando a calçar as luvas.","— Muitas outras coisas dão valor á vida... Isso é uma velha idéa de romantico, meu Ega!"],"f":"Ega desolado, Carlos a concordar, o suspiro, e Carlos a chamar-lhe romântico.","_l":"m5-f13"},{"t":"sublinhar","p":"Toca nas duas palavras que dizem o que governa um romântico e o que não o governa.","frase":"individuos inferiores que se governam na vida pelo sentimento e não pela razão...","certas":[8,12],"f":"«Sentimento» e «razão»: o romântico governa-se pelo primeiro e não pela segunda.","_l":"m5-f13"},{"t":"escolha","voc":true,"p":"Que palavra do texto nomeia a carruagem ligeira que se quebrou em Saint-Cloud?","o":["phaeton","florete","boulevard"],"c":0,"f":"«Phaeton»: carruagem ligeira; em dez anos, foi o único acontecimento de Carlos.","_l":"m5-f13"},{"t":"completar","p":"Como veem o amor os dois romances?","frase":"Em _Amor de Perdição_, o amor é [1]; em _Os Maias_, a paixão é [2] e acaba em tragédia.","lacunas":[{"o":["desmontado pela ironia","absoluto e leva à morte","guardado em segredo"],"c":1},{"o":["desmontada pela ironia","vivida sem obstáculos","impedida pelo pai"],"c":0}],"f":"Romantismo: o amor-paixão vale mais do que a vida; Realismo: a ironia desmonta a paixão.","_l":"m5-f15"},{"t":"completar","p":"Que espaços tem cada romance?","frase":"Camilo escolhe casas de família, conventos e [1]; Eça, a Lisboa social, do Ramalhete ao [2] e a Sintra.","lacunas":[{"o":["cadeia","Paris","Hotel Central","Sintra"],"c":0},{"o":["Hotel Central","cadeia","Bignon","Monchique"],"c":0}],"f":"Camilo: casas, conventos, cadeia; Eça: Ramalhete, Hotel Central, Sintra; espaço íntimo contra espaço social.","_l":"m5-f15"},{"t":"escolha","p":"Como acabam os dois romances?","o":["Teresa, Simão e Mariana mortos; Afonso morto, «Falhámos a vida»","Tadeu e Baltasar mortos; Carlos morre em Paris, dez anos depois","Simão volta da Índia e casa; Ega parte para Paris e não volta","Teresa casa com Baltasar; Carlos casa e fica a viver no Ramalhete"],"c":0,"f":"Camilo mata os três amantes; Eça deixa Afonso morto e dois amigos a fazer contas à vida.","_l":"m5-f15","fe":[null,"Em _Amor de Perdição_ morrem os três amantes, Teresa, Simão e Mariana; em _Os Maias_ Carlos não morre: morre Afonso, e Carlos fica a fazer contas à vida.","Simão não volta: no fim de _Amor de Perdição_ morrem Teresa, Simão e Mariana; em _Os Maias_, é Afonso que morre.","Teresa não casa com Baltasar e morre no convento; Carlos não fica no Ramalhete: no fim, o casarão está «para sempre deshabitado»."]},{"t":"escolha","p":"«sem lagrimas», em «Thereza ergueu-se sem lagrimas», é…","o":["modificador do grupo verbal","complemento oblíquo do verbo","predicativo do sujeito «Thereza»","complemento direto de «ergueu»"],"c":0,"f":"Modificador do grupo verbal: indica modo e não é selecionado pelo verbo; corta-se e a frase aguenta-se.","_l":"m5-f15","fe":[null,"O oblíquo é pedido pelo verbo, como em «entrou no seu quarto»; «sem lagrimas» corta-se e «Thereza ergueu-se» fica inteira.","Não há verbo «ser» a ligar o sujeito a uma qualidade; «sem lagrimas» diz o modo como se ergueu e pode cortar-se.","«Sem lagrimas» não troca por «o» nem «a»: diz o modo como Teresa se ergueu e corta-se sem estragar a frase."]},{"t":"escolha","p":"«Olha que brincadeira, hein!», sem travessão nem verbo declarativo, é…","o":["discurso direto","comentário do narrador","discurso indireto livre"],"c":2,"f":"Indireto livre: a voz de Ega infiltra-se na narração, sem «disse» nem travessão; a exclamação é de Ega, não um comentário do narrador.","_l":"m5-f15"},{"t":"vf","p":"A repetição da descrição do Ramalhete no fim do romance cria uma analepse.","v":false,"f":"Falso: cria estrutura circular; o romance abre e fecha com o mesmo espaço, agravado.","_l":"m5-f15"},{"t":"completar","p":"Como perdem a vida Simão e Carlos?","frase":"Simão perde a vida [1] por amor e honra; Carlos perde-a [2] por ociosidade.","lacunas":[{"o":["aos poucos","de uma vez","sem dar por isso"],"c":1},{"o":["de repente","aos poucos","de uma vez"],"c":1}],"f":"De uma vez e aos poucos: «Dezoito annos!… degradado da patria» contra «Nada mais inoffensivo, mais nullo».","_l":"m5-f15"},{"t":"ordenar","p":"Os acontecimentos lidos no módulo, por ordem:","passos":["Tadeu manda Teresa casar, em 1803","Simão parte para a Índia, em 1807","Os Maias chegam ao Ramalhete, em 1875","Carlos e Ega fazem contas à vida"],"f":"Camilo em 1803 e 1807; Eça em 1875 e no último capítulo, quando Carlos volta a Lisboa depois de dez anos fora.","p2":"De 1803 ao último capítulo de _Os Maias_: em que ordem aconteceu o que leste?","_l":"m5-f15"},{"t":"emparelhar","p":"Liga cada obra ou corrente ao que lhe pertence.","pares":[["_Amor de Perdição_","Camilo Castelo Branco, 1862"],["_Os Maias_","Eça de Queirós, 1888"],["Romantismo","amor-paixão, morte por amor"],["Realismo","ironia, crítica da sociedade"]],"f":"Camilo em 1862, Eça em 1888; o Romantismo morre por amor, o Realismo ironiza e critica.","_l":"m5-f15"},{"t":"escolha","voc":true,"p":"Que palavra nomeia o amor absoluto do Romantismo, que leva à morte?","o":["amor-paixão","diletantismo","ironia"],"c":0,"f":"Amor-paixão: absoluto, vale mais do que a família e a vida, e leva à morte, em Camilo.","_l":"m5-f15"},{"t":"emparelhar","p":"Liga cada romance ao seu amor e ao seu narrador.","pares":[["Amor em Camilo","absoluto, leva à morte"],["Paixão em Eça","desmontada pela ironia"],["Narrador de Camilo","interpela a leitora"],["Narrador de Eça","observador, usa o indireto livre"]],"f":"Camilo: amor absoluto e narrador que fala à leitora; Eça: paixão ironizada e narrador observador.","_l":"m5-f15"},{"t":"emparelhar","p":"Liga cada expressão à explicação da lição.","pares":[["«sem lagrimas»","indica modo; não é selecionado pelo verbo"],["«Olha que brincadeira, hein!»","voz de Ega infiltrada na narração"],["Ramalhete no início e no fim","abre e fecha com o mesmo espaço"]],"f":"Modificador que indica modo; indireto livre com a voz de Ega; estrutura circular do espaço.","_l":"m5-f15"},{"t":"escolha","voc":true,"p":"Que palavra nomeia a falta de Carlos: não fazer nada da vida?","o":["Ociosidade","Diletantismo","Sentimento"],"c":0,"f":"Ociosidade: Carlos falha por não fazer nada; é a crítica realista de Eça.","_l":"m5-f15"},{"t":"escolha","p":"Qual destas ideias pode abrir a comparação entre Simão e Carlos?","o":["Que os dois perdem a vida de maneiras opostas","Que Carlos é feliz em Paris e Simão na Índia","Que Simão e Carlos são o mesmo herói romântico","Que Camilo escreveu o seu romance depois de Eça"],"c":0,"f":"Os dois **perdem a vida, mas de maneiras opostas**: Simão de uma vez, por amor; Carlos aos poucos.","p2":"Com que ideia, certa, abres a comparação entre Simão e Carlos?","_l":"m5-f15","fe":[null,"Nenhum é feliz: Simão perde tudo «por amor», e Carlos concorda com Ega que falharam a vida.","São heróis de tempos opostos: Simão é romântico e morre por amor; Carlos é o diletante que o Realismo ironiza.","É ao contrário: _Amor de Perdição_ é de 1862 e _Os Maias_ de 1888; Camilo escreveu primeiro."]},{"t":"completar","p":"O que diz cada perda do seu tempo?","frase":"Simão perde-se por amor absoluto e honra, exemplo de [1]; Carlos falha por diletantismo, exemplo de [2] em Eça.","lacunas":[{"o":["Romantismo trágico","crítica realista","estrutura circular"],"c":0},{"o":["Romantismo trágico","crítica realista","sugestão biográfica"],"c":1}],"f":"Simão é o Romantismo trágico; Carlos, a crítica realista: cada perda diz o seu tempo.","_l":"m5-f15"},{"t":"vf","p":"«Dezoito annos!… degradado da patria» serve para falar de Carlos, não de Simão.","v":false,"f":"Falso: é a citação para Simão; para Carlos serve «Nada mais inoffensivo, mais nullo».","_l":"m5-f15"},{"t":"vf","p":"Antes de reler. Recupera a descrição do Ramalhete na F10: os pormenores de um espaço podem caracterizar uma família sem um retrato direto de cada pessoa?","v":true,"f":"Confundir caracterização com retrato explícito faz perder o papel dos pormenores. Relê a descrição do Ramalhete e recupera uma relação entre espaço e história familiar.","_l":"m5-f16"},{"t":"escolha","p":"Que contraste organiza os exemplos educativos?","o":["Opõe repetir doutrina e compreender o concreto.","Contrasta aprender por si e dispensar a orientação.","Contrasta praticar desporto e dispensar a leitura."],"c":0,"f":"A comparação opõe prioridades e métodos. O contraste não significa que Carlos cresça sem orientação ou que toda a aprendizagem verbal seja inútil.","fe":["A comparação opõe prioridades e métodos. O contraste não significa que Carlos cresça sem orientação ou que toda a aprendizagem verbal seja inútil.","Confundes aprender por si com ausência de orientação. Relê as intervenções do padre Vasques, de Brown e de Afonso.","Confundes uma prioridade educativa com recusa da leitura. Regressa à discussão sobre o momento de aprender latim e sobre o conhecimento do mundo."],"_l":"m5-f16"}],"licoes":["m5-f10","m5-f16","m5-f11","m5-f12","m5-f14","m5-f13","m5-f15"]}],M="M5",TIT="Narrativa do século XIX",$=function(s,r){return (r||document).querySelector(s)},$$=function(s,r){return Array.prototype.slice.call((r||document).querySelectorAll(s))};window.EPIUnitTaskRoute.mount({units:U,module:M,title:TIT,tasks:[{"number": 1, "title": "Quem decide por quem: vozes de <i>Amor de Perdição</i>", "href": "../tarefas/m5-u1/"}, {"number": 2, "title": "Uma casa, um jantar, uma frase: <i>Os Maias</i>", "href": "../tarefas/m5-u2/"}]});
})();
