var U=[{"n":1,"titulo":"O ideal e a rua","passos":[{"id":"m6-f01","licao":"m6-f01","exs":[],"ativ":["ler","antero-palacio"]},{"id":"m6-f02","licao":"m6-f02","exs":[],"ativ":["ler","antero-deus"]},{"id":"m6-antero-viagem-ao-nada","licao":null,"exs":["m6-antero-viagem-ao-nada"]},{"id":"m6-f13","licao":"m6-f13","exs":[],"ativ":["ler"]},{"id":"m6-f14","licao":"m6-f14","exs":[],"ativ":["ler"]},{"id":"m6-f11","licao":"m6-f11","exs":[],"ativ":["ler"]},{"id":"m6-f06","licao":"m6-f06","exs":[],"ativ":["ler","cesario-avemarias"]},{"id":"m6-f04","licao":"m6-f04","exs":[],"ativ":["ler","gram-oracoes-rua"]}],"emblema":"data:image/jpeg;base64,","simbolo":"<svg class=\"simbolo\" viewBox=\"0 0 48 48\" aria-hidden=\"true\" data-ico=\"estrela\" data-gesto=\"brilha\"><path d=\"M24 6l5 12 13 1-10 8 3 13-11-7-11 7 3-13L6 19l13-1z\"/></svg>","pool":[{"t":"escolha","p":"Quem fala em «O Palacio da Ventura» e o que se sonha?","o":["O sujeito, que se sonha um cavaleiro andante","O sujeito, que se lembra de um cavaleiro antigo","O sujeito, que vê um cavaleiro passar à porta","O sujeito, que acorda um cavaleiro adormecido"],"c":0,"f":"«Sonho que sou um cavalleiro andante» (v. 1): o sujeito sonha-se o próprio cavaleiro, não o vê de fora.","_l":"m6-f01","fe":[null,"Não é uma lembrança: «Sonho que sou» (v. 1) põe o sujeito dentro do sonho, no papel do próprio cavaleiro.","Ninguém passa à porta: quem bate às portas d'ouro (v. 9) é o próprio sujeito, que se sonha cavaleiro.","Não há nenhum cavaleiro adormecido: quem sonha é o sujeito, e no sonho é ele o cavaleiro andante (v. 1)."]},{"t":"completar","p":"Como se organizam as estrofes de «O Palacio da Ventura»?","frase":"Neste poema, os [1] versos distribuem-se por [2] e dois tercetos: 4 + 4 + 3 + 3.","lacunas":[{"o":["doze","dezasseis","catorze"],"c":2},{"o":["duas quadras","três quadras","uma quadra"],"c":0}],"f":"Catorze versos de dez sílabas, duas quadras e dois tercetos: a forma que Antero usa para pensar em verso.","_l":"m6-f01"},{"t":"escolha","p":"O que encontra o cavaleiro quando as portas de ouro se abrem?","o":["Silêncio e escuridão, e nada mais","Uma sala de ouro, sem ninguém à espera","A Ventura, que o recebe em silêncio","A luz fulgurante que tinha visto de fora"],"c":0,"f":"«Silencio e escuridão — e nada mais!» (v. 14): a promessa de luz dá em vazio.","_l":"m6-f01","fe":[null,"O ouro é das portas, vistas de fora («portas d'ouro»); dentro não há sala descrita, só «Silencio e escuridão» (v. 14).","A Ventura não aparece: dentro, o cavaleiro encontra «só» (apenas) «Silencio e escuridão» (v. 13 e 14); ninguém o recebe.","A luz era a do palácio visto de fora, «fulgurante» (v. 7); ao abrir as portas encontra o contrário, «escuridão» (v. 14)."]},{"t":"vf","p":"A chave de ouro deste soneto está na primeira quadra, em «busco anhelante».","v":false,"f":"Falso: a chave de ouro é o último verso, «e nada mais!», que fecha o sentido e o vira.","_l":"m6-f01"},{"t":"escolha","p":"Na alegoria do soneto, o que representa o palácio da Ventura?","o":["O amor de uma senhora inacessível","A promessa de felicidade e de sentido","A morte, que espera por todos"],"c":1,"f":"O cavaleiro é o sujeito, o palácio a promessa de sentido, o vazio a desilusão: alegoria da busca do Ideal.","_l":"m6-f01"},{"t":"completar","p":"Que recurso opõe «fulgurante» (v. 7) a «Silencio e escuridão» (v. 14)?","frase":"Os dois versos formam uma [1] que opõe a [2] prometida à escuridão encontrada.","lacunas":[{"o":["antítese","alegoria","chave de ouro","anáfora"],"c":0},{"o":["luz","porta","espada","dor"],"c":0}],"f":"Antítese: luz e esplendor prometidos contra escuridão e silêncio encontrados.","_l":"m6-f01"},{"t":"completar","p":"O que dizem «Ventura» e «rota» no glossário?","frase":"«Ventura» quer dizer [1]; em «rota a armadura», «rota» quer dizer [2] e combina com a espada quebrada.","lacunas":[{"o":["aventura","viagem","felicidade"],"c":2},{"o":["partida","a caminho","pesada"],"c":0}],"f":"Ventura é felicidade; «rota a armadura» é a armadura partida, não um caminho.","_l":"m6-f01"},{"t":"ordenar","p":"Os quatro tempos do soneto, por ordem:","passos":["Sonha-se cavaleiro em busca do palácio","Exausto e com as armas desfeitas, avista-o fulgurante","Bate à porta e pede que abram","As portas abrem-se: dentro não há nada"],"f":"Busca, visão, apelo, vazio: uma estrofe para cada momento. A sequência termina com a abertura das portas, mas frustra a expectativa de felicidade. O texto diz que a espada está quebrada e a armadura rota; não afirma que o cavaleiro foi ferido.","_l":"m6-f01"},{"t":"versos","p":"Põe os versos do primeiro terceto pela ordem do soneto.","linhas":["Com grandes golpes bato á porta e brado:","Eu sou o Vagabundo, o Desherdado...","Abri-vos, portas d'ouro, ante meus ais!"],"f":"Bate, diz quem é, pede que abram: o apelo vem antes do vazio.","_l":"m6-f01"},{"t":"sublinhar","p":"Toca nos dois adjetivos que dizem o estado do cavaleiro.","frase":"Mas já desmaio, exhausto e vacillante.","certas":[3,5],"f":"«Exhausto» e «vacillante»: cansado e a cambalear, antes de avistar o palácio fulgurante.","_l":"m6-f01"},{"t":"escolha","voc":true,"p":"Que palavra do soneto quer dizer «ansioso»?","o":["anhelante","vacillante","fulgurante"],"c":0,"f":"**Anhelante**, ansioso: «busco anhelante» é a palavra-chave da primeira quadra.","_l":"m6-f01"},{"t":"escolha","p":"Em «Ideal», como define o sujeito a figura que adora?","o":["Pelo que ela não é, numa série de negações","Pela beleza de Vénus, dos lírios e das rosas","Pela força da Amazona que combate a cavalo","Pela sedução de Circe e dos filtros mortais"],"c":0,"f":"«não é feita / De lyrios», «Não tem as formas languidas, divinas / Da antiga Venus», «Não é a Circe», «Nem a Amazona»: o Ideal define-se **pela negação**.","_l":"m6-f02","fe":[null,"Vénus, os lírios e as rosas vêm todos negados: «não é feita / De lyrios», «Não tem as formas languidas, divinas / Da antiga Venus» (v. 1 a 4).","A Amazona também é negada: «Nem a Amazona» (v. 7). O soneto diz o que a adorada não é.","Circe aparece para ser afastada: «Não é a Circe» (v. 5). A figura define-se pela negação."]},{"t":"completar","p":"Como acaba «Ideal»?","frase":"No último terceto, a visão é comparada a uma [1] e chamada nuvem e sonho que não se pode [2] com as mãos.","lacunas":[{"o":["deusa","miragem","estrela"],"c":1},{"o":["tocar","esquecer","ver"],"c":0}],"f":"«É como uma miragem, que entrevejo» e «sonho impalpavel»: o Ideal não se toca nem se nomeia.","_l":"m6-f02"},{"t":"escolha","p":"Em «Na mão de Deus», o que faz o sujeito ao palácio da Ilusão?","o":["Desce dele devagar e deixa-o para trás","Bate à porta de ouro e pede que lhe abram","Entra nele e encontra lá dentro o descanso","Sobe a escada estreita e fica à janela"],"c":0,"f":"«Desci a passo e passo a escada estreita»: já não bate à porta, sai do palácio.","_l":"m6-f02","fe":[null,"Bater à porta era o gesto do cavaleiro de «O Palacio da Ventura»; aqui o sujeito já sai: «Desci a passo e passo a escada estreita».","O descanso não está dentro do palácio: o coração descansa «Na mão de Deus», depois de o sujeito descer a escada (primeira quadra de B).","A escada desce-se, não se sobe: «Desci a passo e passo a escada estreita»; não há janela no soneto."]},{"t":"completar","p":"Como é o coração em «Na mão de Deus»?","frase":"Em B, o coração é comparado a uma [1] que a [2] leva ao colo.","lacunas":[{"o":["flor","nuvem","criança"],"c":2},{"o":["mãe","Ventura","Amazona"],"c":0}],"f":"«Como criança, em lobrega jornada, / Que a mãe leva ao collo agasalhada»: a fé como colo.","_l":"m6-f02"},{"t":"escolha","p":"«Dorme o teu somno, coração liberto» é um exemplo de…","o":["Apóstrofe ao coração","Comparação com o sono","Metáfora da liberdade","Personificação do sono"],"c":0,"f":"Apóstrofe: o sujeito chama o coração e fala-lhe como a uma pessoa.","_l":"m6-f02","fe":[null,"Não há «como» neste verso; o sujeito chama o coração por «tu» («o teu somno») e manda-o dormir.","«Liberto» diz o estado do coração, mas o recurso do verso é falar-lhe diretamente: «Dorme o teu somno, coração».","Não é o sono que ganha gestos de pessoa: é o coração que o sujeito chama e a quem dá uma ordem, «Dorme»."]},{"t":"completar","p":"Que recurso domina em cada soneto?","frase":"Em A domina a [1] «Não é…»; em B, a [2] da criança ao colo.","lacunas":[{"o":["apóstrofe","anáfora","metáfora"],"c":1},{"o":["comparação","personificação","alegoria"],"c":0}],"f":"Enumeração negativa com anáfora em A; comparação e apóstrofe em B: a linha «Recurso dominante» do quadro.","_l":"m6-f02"},{"t":"vf","p":"O palácio de «Na mão de Deus» é outro, sem relação com «O Palácio da Ventura».","v":false,"f":"Falso: é o mesmo palácio, agora chamado «palacio encantado da Illusão», e o sujeito deixa-o para trás.","_l":"m6-f02"},{"t":"escolha","p":"No glossário de B, «depuz» significa…","o":["guardei comigo","pus de lado","depositei no altar"],"c":1,"f":"«Depuz do Ideal e da Paixão / A forma transitoria»: pôs de lado a forma imperfeita.","_l":"m6-f02"},{"t":"sublinhar","p":"Toca nos dois verbos que dizem o que a visão faz ao destino.","frase":"Que ora amostra ora esconde o meu destino...","certas":[2,4],"f":"«Amostra» e «esconde»: a visão mostra e esconde o destino, por isso não tem nome.","_l":"m6-f02"},{"t":"versos","p":"Põe os versos da primeira quadra de «Na mão de Deus» pela ordem.","linhas":["Na mão de Deus, na sua mão direita,","Descançou a final meu coração.","Do palacio encantado da Illusão","Desci a passo e passo a escada estreita."],"f":"Primeiro o descanso, depois a descida do palácio: a ordem do soneto.","_l":"m6-f02"},{"t":"emparelhar","p":"Liga cada recurso ao que faz.","pares":[["Apóstrofe","chamar alguém ou alguma coisa"],["Metáfora","dizer uma coisa por outra"],["Comparação","aproximar duas coisas com «como»"],["Anáfora","repetir a palavra no princípio dos versos"]],"f":"Apóstrofe chama, metáfora diz por outra, comparação usa «como», anáfora repete no princípio.","_l":"m6-f02"},{"t":"escolha","p":"Quando e onde nasceu Cesário Verde, segundo a lição?","o":["Em Lisboa, em 1842","Em Ponta Delgada, em 1855","Em Lisboa, em 1855"],"c":2,"f":"Lisboa, 25 de fevereiro de 1855; 1842 e Ponta Delgada são de Antero.","_l":"m6-f11"},{"t":"completar","p":"Quando e de que morreu Cesário Verde?","frase":"Cesário morreu em [1] de [2] e tinha apenas 31 anos.","lacunas":[{"o":["1886","1887","1891"],"c":0},{"o":["aneurisma","cólera","tuberculose"],"c":2}],"f":"19 de julho de 1886, tuberculose, 31 anos; 1887 é o ano do _Livro_, 1891 o da morte de Antero.","_l":"m6-f11"},{"t":"completar","p":"Como foi publicado _O Livro de Cesário Verde_?","frase":"O _Livro_ foi organizado por [1] e saiu em 1887, numa tiragem de [2] exemplares não postos à venda.","lacunas":[{"o":["Antero de Quental","Silva Pinto","o próprio Cesário"],"c":1},{"o":["200","2000","20"],"c":0}],"f":"Edição póstuma de 1887, do amigo Silva Pinto, na Typographia Elzeveriana: 200 exemplares não postos à venda.","_l":"m6-f11"},{"t":"escolha","p":"«Edição póstuma» quer dizer edição…","o":["publicada depois da morte do autor","publicada pelo próprio autor, em vida","publicada em poucos exemplares, sem venda","publicada aos poucos, em jornais da época"],"c":0,"f":"Cesário morreu em 1886 sem publicar livro; o _Livro_ saiu em 1887.","_l":"m6-f11","fe":[null,"Cesário não publicou nenhum livro em vida; «póstuma» quer dizer depois da morte (o _Livro_ saiu em 1887, ele morreu em 1886).","Os 200 exemplares sem venda descrevem esta edição, mas não são o sentido de «póstuma»: depois da morte do autor.","Os jornais foram onde Cesário publicou em vida; o _Livro_ é póstumo porque saiu depois da morte."]},{"t":"escolha","p":"«Cesário escrevia assim porque trabalhava no comércio» é…","o":["Uma interpretação, que exige prova nos textos","Um facto, confirmado pelas datas e pelos documentos","Uma opinião pessoal, que por isso não se discute","Uma citação, tirada de um poema do _Livro_"],"c":0,"f":"A biografia pode iluminar a obra, mas não a explica toda: interpretação a discutir.","_l":"m6-f11","fe":[null,"As datas confirmam que trabalhou no comércio, não que isso explique a escrita; a ligação é uma leitura a provar nos poemas.","Não é um gosto pessoal: é uma explicação da obra pela vida, e discute-se com versos.","A frase não está em nenhum poema do _Livro_; é uma leitura de quem fala sobre Cesário."]},{"t":"vf","p":"Um documentário tem acesso direto ao que o poeta sentia.","v":false,"f":"Falso: um documentário reconstrói e sugere; não tem acesso à consciência de ninguém.","_l":"m6-f11"},{"t":"ordenar","p":"Como se escreve uma apreciação crítica, por ordem:","passos":["Identificar título, realização e ano","Descrever a organização e quem fala","Comentar duas escolhas, com o momento","Fechar com um juízo fundamentado"],"f":"Identificação, descrição, comentário, juízo: a ordem do género.","_l":"m6-f11"},{"t":"completar","p":"O que faz um documentário, segundo a lição?","frase":"Um documentário [1] o que mostra, [2] o que não serve e defende uma leitura.","lacunas":[{"o":["escolhe","copia","inventa"],"c":0},{"o":["guarda","explica","corta"],"c":2}],"f":"Escolhe o que mostra e corta o que não serve: ver bem é perceber as escolhas de quem filma.","_l":"m6-f11"},{"t":"escolha","voc":true,"p":"Que amigo organizou a edição póstuma do _Livro_, em 1887?","o":["Silva Pinto","Antero de Quental","Cesário Verde"],"c":0,"f":"**Silva Pinto**: o amigo que organizou a edição de 1887, com 200 exemplares não postos à venda.","_l":"m6-f11"},{"t":"emparelhar","p":"Liga cada número ao que diz da vida de Cesário.","pares":[["1855","nasce em Lisboa"],["1886","morre, aos 31 anos"],["1887","sai o _Livro_, póstumo"],["200","exemplares da tiragem"]],"f":"Nasce em 1855, morre em 1886 aos 31 anos, o _Livro_ sai em 1887, 200 exemplares não vendidos.","_l":"m6-f11"},{"t":"escolha","p":"Quem fala em «Ave-Marias» e o que faz?","o":["Um calafate, que volta do trabalho ao anoitecer","O sujeito, que anda pela zona ribeirinha ao anoitecer","Uma varina, que corre pelo cais ao anoitecer"],"c":1,"f":"«Embrenho-me, a scismar, por boqueirões, por beccos»: é o sujeito que deambula; calafates e varinas são o que ele vê.","_l":"m6-f06"},{"t":"escolha","p":"O que revela a lista «Madrid, Paris, Berlim, S. Petersburgo, o mundo!»?","o":["O desejo de partir, longe da cidade que o oprime","As viagens que o sujeito já fez e de que agora se lembra","As cidades cinzentas e londrinas que ele quer evitar","A rota dos navios que saem do cais ao anoitecer"],"c":0,"f":"Vê partir os «que se vão. Felizes!» e enumera até «o mundo!»: quer fugir, mas fica a errar pelos cais.","_l":"m6-f06","fe":[null,"Nada diz que já lá esteve: as cidades ocorrem-lhe ao ver partir os «que se vão. Felizes!» (v. 10); é o que deseja, não o que viveu.","«Londrina» é a cor da Lisboa que o oprime (v. 8); as capitais são o lugar para onde gostaria de ir, como os que partem, «Felizes!».","Não há navios a partir nesta estrofe: quem parte vai de carro «á via ferrea» (v. 10), e a lista acaba em «o mundo!», o desejo de fugir."]},{"t":"completar","p":"Como passa o sujeito do real ao imaginado junto aos cais?","frase":"Junto aos cais, o sujeito evoca as [1] e vê Camões a salvar [2] a nado.","lacunas":[{"o":["obras da cidade","crónicas navais","festas do rio"],"c":1},{"o":["um amigo","uma nau","um livro"],"c":2}],"f":"«E evoco, então, as chronicas navaes» e «Lucta Camões no Sul, salvando um livro a nado!»: do real ao imaginário épico.","_l":"m6-f06"},{"t":"completar","p":"Por que sentidos chegam o gás e o bulício?","frase":"«O gaz extravasado enjôa-me» chega pelo [1] e dá enjoo; «o bulicio», o rumor da rua agitada, chega pela [2] e dá inquietação.","lacunas":[{"o":["olfato","visão","audição"],"c":0},{"o":["olfato","visão","audição"],"c":2}],"f":"Olfato e audição: enjoo e inquietação, duas linhas do quadro dos sentidos.","_l":"m6-f06"},{"t":"completar","p":"Que recurso há em «Seus troncos varonis recordam-me pilastras»?","frase":"Comparar os troncos das varinas a [1] é uma [2] que lhes dá força quase épica.","lacunas":[{"o":["navios","pilastras","árvores"],"c":1},{"o":["comparação","antítese","alegoria"],"c":0}],"f":"Corpos comparados a colunas de pedra: força e grandeza; logo a seguir, os filhos «naufragam nas tormentas».","_l":"m6-f06"},{"t":"escolha","p":"Calafates, carpinteiros e varinas são, no poema, exemplos de…","o":["Imaginário épico, figuras que vêm das epopeias","Tipos sociais, figuras que valem por um grupo","Transfiguração do real, figuras que a imaginação inventa"],"c":1,"f":"Tipos sociais: cada figura vale por um ofício ou por um grupo inteiro.","_l":"m6-f06"},{"t":"vf","p":"A parte I acaba como começa, no sentimento vago do sujeito.","v":false,"f":"Falso: começa no «desejo absurdo de soffrer» e acaba nos «focos de infecção», na miséria concreta das varinas.","_l":"m6-f06"},{"t":"escolha","p":"No glossário, «calafates» são…","o":["Vendedoras de peixe que correm pelo cais","Barcos de carga que atracam no Tejo","Operários que vedam os cascos dos navios"],"c":2,"f":"«Voltam os calafates, aos magotes»: operários dos navios; varinas vendem peixe, fragatas são os barcos.","_l":"m6-f06"},{"t":"sublinhar","p":"Toca na palavra que diz que o desejo de sofrer não tem razão.","frase":"Despertam-me um desejo absurdo de soffrer.","certas":[3],"f":"«Absurdo»: o desejo de sofrer não tem causa; só no fim a miséria lhe dá uma razão.","_l":"m6-f06"},{"t":"versos","p":"Põe os versos da estrofe das «chronicas navaes» pela ordem do poema.","linhas":["E evoco, então, as chronicas navaes:","Mouros, baixeis, heroes, tudo resuscitado!","Lucta Camões no Sul, salvando um livro a nado!","Singram soberbas naus que eu não verei jámais!"],"f":"Evoca, enumera, vê Camões a nado e fecha nas naus que não verá: do real ao imaginário épico.","_l":"m6-f06"},{"t":"escolha","voc":true,"p":"Que palavra da primeira estrofe quer dizer «tristeza sombria»?","o":["soturnidade","bulicio","maresia"],"c":0,"f":"**Soturnidade**: tristeza sombria; com «melancholia», abre o anoitecer das nossas ruas.","_l":"m6-f06"},{"t":"escolha","p":"Em «Sonho que sou um cavaleiro andante», a segunda oração é…","o":["Subordinada substantiva completiva","Subordinada adjetiva relativa restritiva","Oração coordenada copulativa","Subordinada adverbial consecutiva"],"c":0,"f":"Troca-se por «isso»: «Sonho isso». Completa o verbo «sonho»: substantiva completiva.","_l":"m6-f04","fe":[null,"Uma relativa retomaria um nome antes de «que»; aqui «que» vem logo depois do verbo «Sonho» e não retoma nada: «Sonho isso».","Na coordenação nenhuma oração se integra na outra; aqui «que sou um cavaleiro andante» é o que se sonha, o complemento de «Sonho».","Uma consecutiva pediria «tal… que» ou «tão… que»; aqui a oração completa o verbo: «Sonho isso»."]},{"t":"completar","p":"Como se classifica «Mas dentro encontro só» depois de «Abrem-se as portas de ouro»?","frase":"A segunda oração é coordenada [1] e o conector [2] opõe o que se esperava ao que se encontra.","lacunas":[{"o":["copulativa","explicativa","adversativa"],"c":2},{"o":["«e»","«mas»","«pois»"],"c":1}],"f":"«Mas» opõe o que se esperava ao que se encontra: coordenada adversativa.","_l":"m6-f04"},{"t":"escolha","p":"Em «Os filhos que depois naufragam nas tormentas», «que depois naufragam» é…","p2":"Que oração é a que diz algo do nome «filhos»?","o":["Subordinada adjetiva relativa restritiva","Subordinada substantiva completiva de «filhos»","Subordinada adverbial consecutiva","Subordinada substantiva relativa"],"c":0,"f":"«Que» retoma o antecedente **filhos** e funciona como sujeito de «naufragam»; a oração restringe o grupo: **adjetiva relativa restritiva**. A substituição mecânica por «os quais» não é necessária nem segura neste contexto.","g":"fim","_l":"m6-f04","fe":[null,"«Que» não completa o nome: retoma «filhos» e é o sujeito de «naufragam»; isso é uma relativa.","Não há «tal… que» nem «tão… que» a pedir uma consequência; «que» retoma o nome «filhos».","A substantiva relativa não tem antecedente (como «quem parte»); aqui há antecedente, «filhos», retomado por «que»."]},{"t":"completar","p":"Aplica duas operações diferentes: reconhecer um complemento e localizar um antecedente.","p2":"Compara «Sonho que sou um cavaleiro» com «os filhos que naufragam».","frase":"Em «Sonho que sou um cavaleiro», a completiva pode ser retomada por [1]. Em «os filhos que naufragam», «filhos» é o [2] de «que».","lacunas":[{"o":["«isso»","«o qual»","«quando»","«porque»"],"c":0},{"o":["antecedente","conector","predicado","vocativo"],"c":0}],"f":"**Isso** retoma o conteúdo sonhado; **antecedente** é o elemento que o relativo retoma. Não são dois testes de troca equivalentes: a análise da função e da relação vem primeiro.","g":"fim","_l":"m6-f04"},{"t":"escolha","p":"Em «Há tal soturnidade… / Que as sombras… despertam-me», a oração «Que…» é subordinada…","o":["Adverbial consecutiva, por «tal… que»","Adverbial causal, a razão da soturnidade","Adjetiva relativa, a retomar «melancolia»","Substantiva completiva do verbo «Há»"],"c":0,"f":"«tal… que»: a consequência da melancolia. Subordinada adverbial consecutiva.","_l":"m6-f04","fe":[null,"A oração não diz porque há soturnidade: diz o que ela provoca, «despertam-me um desejo absurdo de soffrer»; é uma consequência.","«Que» não retoma «melancolia» (não tem função dentro da oração, cujo sujeito é «as sombras…»); liga-se a «tal»: «tal… que» marca o resultado.","«Há» já tem complemento, «tal soturnidade»; a oração com «que» diz o resultado desse grau, por isso é consecutiva."]},{"t":"vf","p":"Depois de comparar o percurso às linhas de uma pauta, o sujeito justifica essa comparação com «Pois sobem […] as notas […]». Na leitura trabalhada, a oração é coordenada explicativa.","v":true,"f":"**Pois**: as notas de flauta ajudam a justificar a aproximação do percurso a uma pauta. Nesta construção, a leitura trabalhada é de **coordenada explicativa**. O contexto anterior, apresentado no apoio, é necessário para perceber o nexo.","_l":"m6-f04"},{"t":"ordenar","p":"Como se analisa uma frase complexa em verso, por ordem:","passos":["Pôr a frase em ordem direta","Identificar os predicados","Procurar os conectores","Classificar cada oração"],"f":"Ordem direta primeiro; tempos compostos como «tinha lido» contam como um só predicado.","p2":"Ordena os passos para analisar um verso com várias orações.","_l":"m6-f04"},{"t":"completar","p":"Como se chamam, em poesia, a ordem alterada e a falta de conector?","frase":"Desfaz-se primeiro a [1] (a ordem alterada) e conta-se com o [2] quando falta o conector.","lacunas":[{"o":["assíndeto","anáfora","anástrofe"],"c":2},{"o":["anástrofe","assíndeto","apóstrofe"],"c":1}],"f":"Anástrofe em «A mim mesmo pergunto» («Pergunto a mim mesmo»); assíndeto quando duas orações se juntam sem conector.","_l":"m6-f04"},{"t":"sublinhar","p":"Toca na palavra que introduz a oração subordinada.","frase":"Sonho que sou um cavaleiro andante.","certas":[1],"f":"«Que» introduz «que sou um cavaleiro andante»: subordinada substantiva completiva, trocável por «isso».","_l":"m6-f04"},{"t":"emparelhar","p":"Liga cada operação ao exemplo em que ajuda a analisar a oração.","p2":"Que procuras em cada construção para confirmar a relação?","pares":[["Verificar o complemento de «temo»: «temo isso»","«Eu temo que me avives»"],["Localizar o antecedente «filhos»","«Os filhos que depois naufragam»"],["Verificar o valor temporal de «assim que»","«Assim que pela História eu me aventuro»"]],"f":"Na primeira, reconhece o complemento; na segunda, o antecedente e a função do relativo; na terceira, a relação temporal. São operações de análise, não senhas que substituem a leitura.","g":"fim","_l":"m6-f04"},{"t":"completar","voc":true,"p":"Com «Levando» no gerúndio, que oração é «Levando à via férrea os que se vão»?","p2":"A oração introduzida por «levando», que se liga a «Batem os carros», como se denomina?","frase":"«Levando à via férrea os que se vão» é uma oração [1], com o verbo no gerúndio.","lacunas":[{"o":["gerundiva","relativa","completiva","consecutiva","explicativa"],"c":0}],"f":"Oração **gerundiva**: «Levando» está no gerúndio e liga-se à principal «Batem os carros».","g":"fim","_l":"m6-f04"},{"t":"sublinhar","p":"Toca na palavra que coordena as duas orações.","frase":"A mim mesmo pergunto, e não atino","certas":[4],"f":"«E» junta «pergunto» e «não atino», duas orações independentes: coordenada copulativa.","_l":"m6-f04"},{"t":"sublinhar","p":"Toca nas duas palavras que introduzem as orações relativas.","frase":"Chora-me o coração que se enche e que se abisma","certas":[3,7],"f":"Os dois **que** retomam «coração» e introduzem relativas coordenadas entre si por «e». O antecedente e a função do relativo ajudam a reconhecer a construção; não troques mecanicamente por «o qual».","_l":"m6-f04"},{"t":"completar","voc":true,"p":"«Assim que pela História eu me aventuro e alargo»: subordinada adverbial de que tipo?","frase":"Adverbial [1]","lacunas":[{"o":["temporal","causal","consecutiva"],"c":0}],"f":"Adverbial **temporal**: «assim que» responde a «quando?», logo que me aventuro.","_l":"m6-f04"},{"t":"emparelhar","p":"Liga os conectores às relações trabalhadas nos exemplos desta lição.","pares":[["mas","adversativa"],["e","copulativa"],["pois","explicativa"]],"f":"Nos exemplos analisados: **mas** estabelece contraste, **e** adição e **pois** justificação. Classifica a relação na construção completa, não o conector isolado.","_l":"m6-f04"},{"t":"escolha","p":"Em «o nome que dê a essa visão», que observação permite reconhecer a relativa?","o":["A oração pode ser retirada sem se perder nenhuma informação","«Que» retoma «nome» e integra a oração que restringe o nome procurado","Qualquer oração iniciada por «que» é relativa"],"c":1,"f":"Identifica o antecedente **nome** e a relação da oração com ele. A regra «todo o que é relativo» falha; trocar sempre por «o qual» também não é seguro.","_l":"m6-f04"},{"t":"vf","p":"Em «os que se vão», a oração relativa tem um antecedente expresso.","v":false,"f":"Falso: «os que se vão» é substantiva relativa, sem antecedente, dentro do complemento.","_l":"m6-f04"},{"t":"escolha","p":"Que relação de enunciação se constrói nesta primeira quadra?","o":["Um narrador relata a vida inteira de Antero na terceira pessoa","Uma voz dirige-se a um «tu», um poeta que aparece recolhido","Uma multidão conta a sua própria história sem destinatário","O poeta destinatário já responde à voz que o chama"],"c":1,"f":"O título e o «Tu» sustentam a interpelação. O recorte não é uma biografia nem contém a resposta do destinatário. Distinguir quem fala e a quem fala evita tomar qualquer voz poética como confissão direta do autor.","_l":"m6-f13","fe":["Não há narração da vida de Antero: há um «Tu» a quem a voz fala (primeiro verso), e o título diz que é um poeta.",null,"Há destinatário, o «Tu» do primeiro verso; e quem fala é uma voz, não uma multidão a contar a sua história.","O destinatário não responde: dorme, «Posto á sombra dos cedros seculares»; só a voz fala."]},{"t":"escolha","p":"O que acrescentam «multidões» e «teus irmãos» ao chamamento?","o":["O apelo desloca o poeta de uma posição isolada para uma relação coletiva","O poema identifica pelo nome civil cada uma das pessoas que se erguem na multidão","A voz afirma que o poeta e a multidão são irmãos de sangue, filhos dos mesmos pais","O destinatário deixa de ser poeta e passa a narrador da história das multidões"],"c":0,"f":"«Irmãos» constrói uma relação de proximidade e solidariedade com a multidão. É uma pertença figurada: não um registo genealógico nem a identificação de todas as pessoas.","_l":"m6-f13","fe":[null,"Ninguém é nomeado: «a grande voz das multidões» é coletiva, e «teus irmãos» diz uma pertença, não nomes.","«Irmãos» é figurado: une o poeta à multidão que se ergue; não é um registo de família.","O destinatário continua a ser o poeta chamado a erguer-se («Ergue-te pois, soldado do Futuro»); não passa a narrar nada."]},{"t":"vf","p":"Antes de reler. Recupera a distinção entre tese e argumento: a confiança em quem fala substitui a razão apresentada para defender uma ideia?","v":false,"f":"Confundir credibilidade e fundamento dispensa o exame da tese. Relê a relação entre posição e razões na unidade de Antero e procura o que sustenta a conclusão.","_l":"m6-f14"},{"t":"escolha","p":"Que relação com o público é proposta?","o":["A discussão das ideias admite a discordância.","A escuta das ideias pressupõe o acordo mútuo.","A discussão das ideias adia a avaliação crítica."],"c":0,"f":"O orador distingue ouvir e discutir de aderir. A relação com o público pode manter-se mesmo quando as opiniões não coincidem.","fe":["O orador distingue ouvir e discutir de aderir. A relação com o público pode manter-se mesmo quando as opiniões não coincidem.","Transformas o acordo em condição de escuta. Relê a recusa de impor uma opinião e a abertura à discordância.","Confundes abertura ao público com suspensão da crítica. Regressa ao convite para discutir ideias e à responsabilidade de fundamentar."],"_l":"m6-f14"}],"licoes":["m6-f01","m6-f02","m6-f13","m6-f14","m6-f11","m6-f06","m6-f04"]},{"n":2,"titulo":"A cidade inteira","passos":[{"id":"m6-f07","licao":"m6-f07","exs":[],"ativ":["ler","cesario-noite"]},{"id":"m6-cesario-noite-inteira","licao":null,"exs":["m6-cesario-noite-inteira"]},{"id":"m6-f05","licao":"m6-f05","exs":[],"ativ":["ler"]},{"id":"m6-f08","licao":"m6-f08","exs":[],"ativ":["ler","sam-chelas"]},{"id":"m6-f12","licao":"m6-f12","exs":[],"ativ":["ler"]},{"id":"m6-f15","licao":"m6-f15","exs":[],"ativ":["ler"]},{"id":"m6-f09","licao":"m6-f09","exs":[],"ativ":["ler"]}],"emblema":"data:image/jpeg;base64,","simbolo":"<svg class=\"simbolo\" viewBox=\"0 0 48 48\" aria-hidden=\"true\" data-ico=\"lampiao\"><path d=\"M18 10h12l2 6H16z\"/><path d=\"M16 16h16v14H16z\"/><path d=\"M20 30h8v4h-8z\"/><path d=\"M24 34v8\"/><path d=\"M20 42h8\"/><path d=\"M24 4v6\"/></svg>","pool":[{"t":"escolha","p":"Como abre «Noite Fechada» e que imagem dá da cidade?","o":["Com as grades das cadeias: uma cidade prisão","Com os sinos da sé: uma cidade devota","Com as montras dos ourives: uma cidade elegante","Com as tascas e os cafés: uma cidade iluminada"],"c":0,"f":"«Toca-se as grades, nas cadeias»: a noite fecha-se e a cidade ganha grades.","_l":"m6-f07","fe":[null,"A sé e as cruzes aparecem depois (v. 7), com o sujeito já mórbido; o primeiro som é o das grades: «Toca-se as grades, nas cadeias» (v. 1).","As montras dos ourives só surgem no verso 36, com as «elegantes»; a parte abre com as grades das cadeias.","As tascas e os cafés iluminam-se na terceira estrofe (v. 10); o poema abre com um som que «mortifica»: as grades das cadeias."]},{"t":"completar","p":"Que antítese social há em «Inflamma-se um palacio em face de um casebre»?","frase":"A luz de um [1] diante de um [2] põe riqueza e miséria lado a lado.","lacunas":[{"o":["convento","palácio","quartel"],"c":1},{"o":["aljube","café","casebre"],"c":2}],"f":"A linha «Palácio e casebre» do quadro: desigualdade numa só imagem.","_l":"m6-f07"},{"t":"escolha","p":"Como se relacionam «o real e a analyse» e «Tornam-se mausoléos as armações fulgentes»?","o":["A observação das montras transforma-se numa imagem de morte","A análise exclui qualquer imagem criada pela imaginação","O sujeito descreve sepulturas reais, sem transformar o que vê","O brilho das montras é um pormenor sem efeito na visão da cidade"],"c":0,"f":"As **armações** são as montras; os **mausoléos** remetem para sepulcros. A observação da rua transforma-se numa imagem que pode acentuar a opressão. O programa realista parte do real e da análise; não elimina a imaginação.","_l":"m6-f07","fe":[null,"O próprio verso transforma montras em «mausoléos». Real e imaginação articulam-se: há um dado observado e uma imagem criada a partir dele.","São as montras que se tornam «mausoléos» pela linguagem; o verso não diz que as lojas foram substituídas por sepulturas.","A passagem de «fulgentes» a «mausoléos» liga o brilho das lojas a uma imagem de morte. O pormenor ajuda a construir uma visão sombria da cidade."]},{"t":"completar","p":"Como acaba «Horas Mortas»?","frase":"No último verso, a Dor humana tem marés de [1] e é comparada a um sinistro [2] que enche a cidade.","lacunas":[{"o":["sal","luz","fel"],"c":2},{"o":["rio","mar","céu"],"c":1}],"f":"«Marés, de fel, como um sinistro mar»: a dor amarga enche a cidade e retoma o Tejo do início.","_l":"m6-f07"},{"t":"escolha","p":"Em «Um cheiro salutar e honesto a pão no forno», «honesto» é…","o":["Qualidade moral atribuída a uma sensação","Duas ideias opostas postas lado a lado","Mistura de dois sentidos na mesma expressão","Figura que vale por um grupo inteiro"],"c":0,"f":"«Honesto» atribui ao cheiro uma qualidade moral associada a quem produz o pão: é uma hipálage. A expressão não deve ser classificada como sinestesia apenas por associar uma sensação a uma qualidade moral; a sinestesia cruza domínios sensoriais.","_l":"m6-f07","fe":[null,"Para haver antítese seriam precisas duas ideias opostas; «salutar» e «honesto» não se opõem, somam-se no cheiro do pão.","Na sinestesia cruzam-se dois sentidos (como em «um silêncio frio»); aqui há um só sentido, o olfato, e «honesto» é uma qualidade moral.","Valer por um grupo é o que fazem os tipos sociais (o forjador, o cauteleiro); «honesto» é uma qualidade de pessoa dada ao cheiro."]},{"t":"completar","p":"Quem vive «no valle escuro das muralhas» e como é essa cidade?","frase":"Os [1] vivem numa cidade que é [2] sem árvores, em contraste com o campo.","lacunas":[{"o":["soldados","emparedados","bebedores"],"c":1},{"o":["um convento","um teatro","uma prisão"],"c":2}],"f":"«Mas se vivemos, os emparedados»: a cidade como prisão, em contraste com o campo.","_l":"m6-f07"},{"t":"vf","p":"Em IV, o sonho «Se eu não morresse, nunca!» é cortado por um «Mas» que o devolve à cidade.","v":true,"f":"Verdadeiro: «Mas se vivemos, os emparedados»: da chimera à prisão, o movimento de todo o poema.","_l":"m6-f07"},{"t":"escolha","p":"No glossário de II, «aljube» é…","o":["prisão","igreja","tabacaria"],"c":0,"f":"«O aljube, em que hoje estão velhinhas e creanças»: a prisão; os estancos são as tabacarias.","_l":"m6-f07"},{"t":"sublinhar","p":"Toca nas duas palavras com que o sujeito chama a cidade.","frase":"Triste cidade! Eu temo que me avives","certas":[0,1],"f":"«Triste cidade!»: o sujeito fala à cidade como a uma pessoa, apóstrofe, antes de temer a paixão.","_l":"m6-f07"},{"t":"versos","p":"Põe os versos da última estrofe de «Horas Mortas» pela ordem.","linhas":["E, enorme, n'esta massa irregular","De predios sepulchraes, com dimensões de montes,","A Dôr humana busca os amplos horisontes,","E tem marés, de fel, como um sinistro mar!"],"f":"Da massa de prédios à Dor humana feita mar: o poema fecha-se em círculo.","_l":"m6-f07"},{"t":"emparelhar","p":"Liga cada tipo ou imagem ao que revela da cidade.","pares":[["Presos e soldados","cidade repressiva e doente"],["O forjador e o padeiro","valorização do trabalho honesto"],["Palácio e casebre","riqueza e miséria lado a lado"],["«os emparedados»","a cidade como prisão"]],"f":"Repressão, trabalho honesto, desigualdade, prisão: as quatro linhas do quadro dos tipos sociais.","_l":"m6-f07"},{"t":"escolha","p":"O que é o étimo de uma palavra?","o":["A palavra de origem, muitas vezes latina","A grafia que a palavra tinha no século XIX","O sinónimo mais antigo que o dicionário regista","A palavra que a reforma ortográfica fixou"],"c":0,"f":"O étimo é a origem: _plenu-_ dá «cheio» e «pleno».","_l":"m6-f05","fe":[null,"A grafia antiga é outra coisa («occidental» é uma grafia do século XIX); o étimo é a palavra de onde a palavra nasceu, como _plenu-_.","Um sinónimo tem sentido parecido; o étimo é a origem da própria palavra, como _plenu-_ para «cheio».","A reforma ortográfica fixa a grafia de hoje («ocidental»); o étimo é a palavra de origem, muitas vezes latina."]},{"t":"completar","p":"O que são palavras divergentes?","frase":"Palavras divergentes nascem do mesmo [1] por duas vias, uma [2] e outra erudita.","lacunas":[{"o":["étimo","prefixo","dicionário","sufixo"],"c":0},{"o":["popular","recente","estrangeira","técnica"],"c":0}],"f":"Via popular: evolução fonética lenta; via erudita: tomada mais tarde, próxima do latim.","_l":"m6-f05"},{"t":"escolha","p":"Do étimo _clave-_ nasceram…","o":["«chave» (erudita) e «clave» (popular)","«chave» (popular) e «clave» (erudita)","«chave» e «chaveiro», ambas populares"],"c":1,"f":"«chave» evoluiu devagar na fala; «clave» veio depois, próxima do latim.","_l":"m6-f05"},{"t":"completar","p":"Que pares vieram de _macula-_ e de _articulu-_?","frase":"De _macula-_ vieram [1] e «mácula»; de _articulu-_ vieram «artelho» e [2] pela via erudita.","lacunas":[{"o":["mágoa","mala","mancha"],"c":2},{"o":["artigo","artífice","arteiro"],"c":0}],"f":"Mancha ou malha e mácula; artelho e artigo ou artículo: um étimo, duas caras.","_l":"m6-f05"},{"t":"escolha","p":"«melancholia» passou a «melancolia» porque…","o":["o _ch_ com valor de [k] passou a _c_","a consoante dupla ficou reduzida a uma só","o _y_ passou a _i_, com acento gráfico","o acento gráfico da palavra foi suprimido"],"c":0,"f":"_ch_ lia-se [k]; a reforma escreveu _c_. A consoante dupla é o caso de «occidental».","_l":"m6-f05","fe":[null,"Consoante dupla é o caso de «occidental»; em «melancholia» o que muda é o _ch_, lido [k], que passa a _c_.","O _y_ passou a _i_ em «lyrios», «lírios»; «melancholia» não tem _y_.","Perder o acento é o caso de «sómente»; «melancholia» não tinha acento, perdeu o _h_ de _ch_."]},{"t":"completar","p":"O que mudou em «occidental» e em «lyrios»?","frase":"Em «occidental» simplificou-se a [1]; em «lyrios», o _y_ passou a [2] com acento gráfico.","lacunas":[{"o":["vogal inicial","consoante dupla","letra final"],"c":1},{"o":["_i_","_e_","_u_"],"c":0}],"f":"«ocidental», «lírios»: consoante dupla simplificada; _y_ passa a _i_, com acento gráfico.","_l":"m6-f05"},{"t":"vf","p":"«sómente» perdeu o acento na grafia de hoje: «somente».","v":true,"f":"Verdadeiro: acento suprimido; «egrejas» fixou a vogal inicial em «i»: «igrejas».","_l":"m6-f05"},{"t":"escolha","p":"Segundo o modelo da lição, «varina» guarda a origem de…","o":["Vara, o pau com que pesavam o peixe","Ovar, terra das vendedoras de peixe","Varanda, onde vendiam o peixe"],"c":1,"f":"«varina: de Ovar, terra de onde vinham as vendedoras de peixe» (_Dicionário Priberam_, entrada «varina»).","_l":"m6-f05"},{"t":"emparelhar","p":"Liga cada grafia do século XIX ao que mudou na de hoje.","pares":[["occidental","consoante dupla simplificada"],["melancholia","_ch_ com valor de [k] passou a _c_"],["lyrios","_y_ passou a _i_, com acento"],["egrejas","vogal inicial fixada em _i_"]],"f":"Consoante dupla, _ch_ por _c_, _y_ por _i_, vogal inicial: quatro linhas do quadro das grafias.","_l":"m6-f05"},{"t":"escolha","voc":true,"p":"Do étimo _macula-_, qual é a palavra da via erudita?","o":["mácula","mancha","malha"],"c":0,"f":"**Mácula**: via erudita, próxima do latim; «mancha» e «malha» vieram pela via popular.","_l":"m6-f05"},{"t":"escolha","voc":true,"p":"Qual é a grafia de hoje de «occidental»?","o":["ocidental","occidental","oçidental","ocsidental"],"c":0,"f":"**Ocidental**: a consoante dupla simplificou-se; é a palavra do título do poema de Cesário.","_l":"m6-f05","fe":[null,"«Occidental» é a grafia de 1887, com consoante dupla; hoje escreve-se com um só _c_: «ocidental».","O _ç_ não se usa antes de _i_; a palavra de hoje é «ocidental».","O som [s] escreve-se aqui com _c_, não com _cs_: «ocidental»."]},{"t":"completar","voc":true,"p":"Do étimo _articulu-_, que palavra veio pela via popular?","frase":"Do étimo _articulu-_, pela via popular, veio [1].","lacunas":[{"o":["artelho","artigo","artículo"],"c":0}],"f":"**Artelho**: via popular; «artigo» e «artículo» são as formas eruditas do mesmo étimo.","_l":"m6-f05"},{"t":"emparelhar","p":"Liga cada étimo latino às duas palavras que dele nasceram.","pares":[["_plenu-_","cheio e pleno"],["_clave-_","chave e clave"],["_macula-_","mancha e mácula"],["_articulu-_","artelho e artigo"]],"f":"Cheio e pleno, chave e clave, mancha e mácula, artelho e artigo: um étimo, duas vias.","_l":"m6-f05"},{"t":"emparelhar","p":"Liga cada termo da etimologia ao que significa.","pares":[["Étimo","palavra de origem, muitas vezes latina"],["Via popular","evolução fonética lenta"],["Via erudita","tomada mais tarde, próxima do latim"]],"f":"Étimo é a origem; a via popular evolui devagar; a via erudita vem tarde, perto do latim.","_l":"m6-f05"},{"t":"escolha","p":"Qual destas palavras veio pela via erudita?","o":["clave","chave","cheio","mancha"],"c":0,"f":"«Clave» ficou perto do latim «clave-»; «chave» e «cheio» evoluíram devagar na fala.","_l":"m6-f05","fe":[null,"«Chave» veio de _clave-_ pela via popular, gasta na fala; a forma erudita, perto do latim, é «clave».","«Cheio» é a forma popular de _plenu-_; a erudita é «pleno».","«Mancha» é popular, de _macula-_; a erudita é «mácula»."]},{"t":"vf","p":"«mancha» e «malha» vieram as duas do étimo _macula-_ pela via popular.","v":true,"f":"Verdadeiro: o quadro dá «mancha, malha» na via popular e «mácula» na erudita.","_l":"m6-f05"},{"t":"escolha","p":"Exemplo inventado para «Batem os carros de aluguer» (I): A mostra um táxi e escreve «é um carro»; B mostra uma fila em movimento e explica a agitação da rua. Qual fundamenta melhor a relação?","o":["B, porque liga uma escolha de imagem ao movimento sugerido pelo verso.","A, porque identificar o objeto basta para explicar o efeito do verso.","B, porque uma imagem atual dispensa o verso e a indicação da parte.","A, porque uma relação não literal exige evitar veículos na imagem."],"c":0,"f":"B explica a escolha a partir do **movimento** do verso. A presença de um carro, por si só, não explica o efeito. Outras imagens podem funcionar se a relação for fundamentada.","_l":"m6-f08","fe":[null,"Identificar o carro reconhece o objeto, mas falta explicar a escolha e o seu efeito.","A atualização da imagem não dispensa a citação exata nem a parte do poema.","A relação pode incluir veículos; o que conta é explicar o que a imagem transforma ou realça."],"p2":"Para «Batem os carros de aluguer» (I), A identifica um táxi; B relaciona uma fila em movimento com a agitação da rua. Neste exemplo inventado, que justificação avança mais?","g":"fim"},{"t":"completar","p":"Por onde passa o percurso do projeto?","frase":"O percurso parte do [1] e acompanha as [2] partes do poema, do anoitecer à madrugada.","lacunas":[{"o":["Cais do Sodré","Santa Catarina","Bica"],"c":0},{"o":["três","duas","quatro"],"c":2}],"f":"Cais do Sodré, quatro partes, até às horas mortas da madrugada.","_l":"m6-f08"},{"t":"escolha","p":"Que regra de produção vale para quem aparece reconhecível nas imagens?","o":["Pedir-lhe autorização antes","Desfocar-lhe o rosto depois","Fotografar à distância, sem avisar","Avisar o docente no dia seguinte"],"c":0,"f":"Pedir autorização; nada de fotografar às escondidas nem pessoas vulneráveis sem consentimento.","_l":"m6-f08","fe":[null,"Desfocar depois não substitui o pedido: a regra é pedir autorização antes a quem aparece reconhecível.","Fotografar sem avisar é o que a regra proíbe: «nada de fotografar às escondidas».","O docente não autoriza por quem aparece; quem decide é a pessoa fotografada, e antes."]},{"t":"completar","p":"Como se liga cada imagem ao poema?","frase":"Cada imagem liga-se a um [1] citado com a parte, numa relação clara e não [2] com o texto.","lacunas":[{"o":["verso","tipo social","lugar"],"c":0},{"o":["visual","literal","poética"],"c":1}],"f":"Relação clara e não literal entre verso e imagem; progressão da tarde à madrugada.","_l":"m6-f08"},{"t":"ordenar","p":"O processo do projeto, por ordem:","passos":["Testar três percursos, escolher um e fazer o guião","Fotografar ou filmar","Selecionar, com registo das rejeitadas","Ensaiar a apresentação"],"f":"Percursos e guião, captação, seleção com registo das rejeitadas, ensaio.","_l":"m6-f08"},{"t":"vf","p":"O percurso pode demorar o tempo que o grupo quiser, desde que seja seguro.","v":false,"f":"Falso: a pé, no máximo 45 minutos, e seguro; sair em grupo e dentro do horário combinado.","_l":"m6-f08"},{"t":"escolha","p":"A memória descritiva é individual e tem…","o":["120 a 150 palavras, com título e ano","90 a 110 palavras, com duas citações","100 a 130 palavras, com o verso e a parte"],"c":2,"f":"Primeira frase: o verso, entre aspas, e a parte; depois a imagem e a ligação.","_l":"m6-f08"},{"t":"completar","p":"Plano inventado para «O gaz extravasado enjôa-me, perturba» (I): o grupo quer criar incómodo sem mostrar gás. Completa a justificação.","frase":"A câmara aproxima-se de um corredor apertado e o som torna-se irregular: ligamos estas escolhas ao [1] do sujeito, mas não afirmamos que o poema descreve [2].","lacunas":[{"o":["mal-estar","entusiasmo","alívio","desprezo"],"c":0},{"o":["esse corredor","uma sensação","uma perturbação","um cheiro"],"c":0}],"f":"O corredor e o som são uma **transposição inventada do mal-estar**: não são pormenores descritos neste verso. Outra solução também é possível, desde que expliques a ligação ao texto.","_l":"m6-f08","p2":"A partir de «O gaz extravasado enjôa-me, perturba» (I), o grupo inventa um corredor apertado e som irregular. Como distingue a sua proposta da informação do verso?","g":"fim"},{"t":"emparelhar","p":"Liga cada parte do poema ao seu título.","pares":[["Parte I","Ave-Marias"],["Parte II","Noite Fechada"],["Parte III","Ao Gás"],["Parte IV","Horas Mortas"]],"f":"Ave-Marias, Noite Fechada, Ao Gás, Horas Mortas: do anoitecer à madrugada, a partir do Cais do Sodré.","_l":"m6-f08"},{"t":"escolha","voc":true,"p":"Como se chama o texto individual, de 100 a 130 palavras, que explica uma escolha do grupo?","o":["memória descritiva","apreciação crítica","guião de leitura","reportagem escrita"],"c":0,"f":"**Memória descritiva**: o verso com a parte, a imagem ou o som, e a ligação entre os dois.","_l":"m6-f08","fe":[null,"A apreciação crítica julga uma obra feita por outros; aqui explica-se uma escolha do próprio grupo: verso, imagem e ligação.","O guião de leitura é a entrega do curso de Interpretação; o texto individual que explica uma escolha é a memória descritiva.","A reportagem conta o que aconteceu; a memória descritiva explica o verso, a imagem e a ligação entre os dois."]},{"t":"escolha","p":"Que forma domina em Antero e que forma domina em Cesário?","o":["Soneto em Antero; quadras de versos longos em Cesário","Quadras de versos longos em Antero; soneto em Cesário","Soneto nos dois, sempre com chave de ouro","Quadras curtas nos dois, com refrão"],"c":0,"f":"Antero pensa em soneto; Cesário conta em quadras de alexandrinos e decassílabos.","_l":"m6-f09","fe":[null,"Está trocado: o soneto com chave de ouro é de Antero («O Palacio da Ventura»); as quadras de versos longos são de Cesário.","Cesário não escreve sonetos nos poemas estudados: «O Sentimento dum Ocidental» é feito de quadras de versos longos.","Quadras curtas com refrão lembram a lírica tradicional; Antero usa o soneto e Cesário quadras de versos longos, sem refrão."]},{"t":"completar","p":"Que temas tem cada poeta, segundo o quadro?","frase":"Antero trata da angústia existencial e do [1]; Cesário, da cidade e dos [2] que a povoam.","lacunas":[{"o":["Ideal","Tejo","campo"],"c":0},{"o":["heróis épicos","tipos sociais","cavaleiros andantes"],"c":1}],"f":"Antero: angústia, Ideal, morte, Deus; Cesário: cidade, tipos sociais, trabalho, campo e cidade.","_l":"m6-f09"},{"t":"escolha","p":"Em «O Palacio da Ventura», o último verso funciona como…","o":["chave de ouro","refrão que se repete","mote para glosar","epígrafe do poema"],"c":0,"f":"Fecho que concentra e inverte o sentido: «e nada mais!».","_l":"m6-f09","fe":[null,"Um refrão repete-se ao longo do poema; «e nada mais!» só aparece uma vez, no fim, e vira o sentido.","O mote vem no princípio e é glosado nas voltas; aqui o verso decisivo é o último.","A epígrafe vem antes do poema, citada de outro autor; o último verso de Antero fecha e concentra o sentido."]},{"t":"completar","p":"Distingue a transferência de uma qualidade moral do cruzamento de sentidos.","p2":"Compara o verso do cheiro com o exemplo inventado «um som azul».","frase":"No verso «cheiro […] honesto», a deslocação da qualidade moral exemplifica [1]; no exemplo inventado «um som azul», audição e visão cruzam-se numa [2].","lacunas":[{"o":["hipálage","anáfora","apóstrofe","enumeração"],"c":0},{"o":["sinestesia","anáfora","apóstrofe","enumeração"],"c":0}],"f":"**Hipálage**: uma propriedade é deslocada para outro elemento da situação. **Sinestesia**: cruzam-se domínios sensoriais, aqui audição e visão. Explica a operação antes de fixar o nome; «um som azul» é apenas um exemplo didático.","g":"fim","_l":"m6-f09"},{"t":"escolha","p":"«cheio» e «pleno» são…","o":["palavras homónimas","palavras divergentes","antónimos"],"c":1,"f":"Mesmo étimo, _plenu-_, vias popular e erudita.","_l":"m6-f09"},{"t":"completar","p":"Como se classifica «que me avives» em «Eu temo que me avives / Uma paixão defunta»?","frase":"A oração «que me avives» é uma subordinada [1] [2] dentro da frase complexa.","lacunas":[{"o":["substantiva","adjetiva","adverbial"],"c":0},{"o":["relativa","completiva","causal"],"c":1}],"f":"Teste: «Eu temo isso». Completa o verbo «temo».","_l":"m6-f09"},{"t":"vf","p":"A comparação desta lição descreve tendências dos poemas estudados; não reserva cada recurso expressivo a um único poeta.","p2":"As tendências aqui comparadas não impedem os dois poetas de usar recursos semelhantes.","v":true,"f":"Verdadeiro: o esquema ajuda a comparar estes poemas, mas não substitui a leitura nem divide todos os recursos entre autores. Procura um indício que sustente a comparação e outro que obrigue a limitá-la.","g":"fim","_l":"m6-f09"},{"t":"ordenar","p":"A resposta de desenvolvimento da revisão, por ordem:","passos":["Decidir na primeira frase se concordas","Citar um verso de cada poeta","Fechar com o que os dois têm em comum","Contar as palavras: 100 a 130"],"f":"Tese, um verso de cada, conclusão com matiz e, no fim, a contagem das palavras.","p2":"Ordena a resposta de desenvolvimento, da tese à contagem final das palavras.","_l":"m6-f09"},{"t":"sublinhar","p":"Toca na palavra que dá ao cheiro uma qualidade moral.","frase":"Um cheiro salutar e honesto a pão no forno","certas":[4],"f":"**Honesto**: a qualidade moral é deslocada para o cheiro do pão — hipálage. Esta transferência pode valorizar o trabalho ligado ao pão; a presença do olfato, sozinha, não constitui cruzamento de dois sentidos.","_l":"m6-f09"},{"t":"emparelhar","p":"Liga cada poeta ao que o quadro diz da forma e do real.","pares":[["Antero, forma","soneto"],["Cesário, forma","quadras de versos longos"],["Antero, real","pensado, conceptual"],["Cesário, real","observado e transfigurado"]],"f":"Antero: soneto e real pensado; Cesário: quadras longas e real observado e transfigurado.","_l":"m6-f09"},{"t":"escolha","voc":true,"p":"Que recurso de Antero é uma história em que cada elemento representa uma ideia?","o":["alegoria","apóstrofe","metáfora","personificação"],"c":0,"f":"**Alegoria**: o cavaleiro, o palácio e o vazio representam a busca do Ideal.","_l":"m6-f09","fe":[null,"A apóstrofe é chamar alguém ou alguma coisa; aqui ninguém é chamado: cavaleiro, palácio e vazio formam uma história em que cada elemento vale por uma ideia.","A metáfora diz uma coisa por outra num ponto; a alegoria estende-se a toda a história: cavaleiro, palácio, vazio.","Personificar é dar gestos de pessoa a uma coisa; aqui cada elemento da história representa uma ideia: alegoria."]},{"t":"sublinhar","p":"Toca na palavra que diz o que o palácio promete.","frase":"O palacio encantado da Ventura","certas":[4],"f":"«Ventura» é felicidade: o palácio promete-a e, aberto, só tem silêncio e escuridão.","_l":"m6-f09"},{"t":"escolha","voc":true,"p":"Que recurso cruza audição e visão no exemplo inventado «um som azul»?","o":["sinestesia","hipérbole","enumeração"],"c":0,"f":"**Sinestesia**: som remete para a audição e azul para a visão. O exemplo é didático, não uma citação de Cesário ou Antero.","_l":"m6-f09"},{"t":"completar","voc":true,"p":"Se «cheio» veio pela via popular, por que via veio «pleno»?","frase":"Via [1]","lacunas":[{"o":["erudita","popular","latina"],"c":0}],"f":"Via **erudita**: «pleno» tomou-se mais tarde, próximo do latim; «cheio» é a via popular.","_l":"m6-f09"},{"t":"emparelhar","p":"Liga a oração destacada em cada exemplo à sua classificação.","p2":"Distingue as orações destacadas nos versos e no exemplo didático.","pares":[["«Sonho **que sou um cavaleiro**»","substantiva completiva"],["«o nome **que dê a essa visão**»","adjetiva relativa"],["Exemplo didático: «Há tal melancolia **que as sombras me inquietam**»","adverbial consecutiva"]],"f":"Completiva: verifica o complemento de «Sonho». Relativa: identifica o antecedente «nome». Consecutiva: confirma a relação de resultado em «tal… que». Trocar sempre «que» por «o qual» não é um teste seguro.","g":"fim","_l":"m6-f09"},{"t":"escolha","p":"Que afirmação distingue a prova do verso de uma generalização que ele não sustenta?","p2":"O que permite defender «Um cheiro salutar e honesto a pão no forno», sem ultrapassar a prova?","o":["O verso associa uma sensação olfativa a «honesto», permitindo discutir a valorização do trabalho ligado ao pão","O cheiro referido prova que todos os habitantes de Lisboa trabalham honestamente, como quem fez aquele pão no forno","A palavra «honesto» comprova a conduta real de cada pessoa que fabricou aquele pão: o verso é um documento","Como o verso não nomeia o Ideal, prova que Cesário nunca desenvolve ideias abstratas em nenhum dos poemas"],"c":0,"f":"A primeira afirmação localiza **cheiro** e **honesto** e propõe um efeito de sentido. A leitura precisa de ser desenvolvida no contexto; o verso não funciona como documento da conduta de todas as pessoas nem como regra sobre toda a obra.","g":"fim","fe":[null,"Um recorte não prova a conduta de toda a cidade. Limita a conclusão ao efeito das palavras e ao contexto do poema.","O adjetivo participa numa construção poética: não é prova documental sobre pessoas reais.","A ausência de um tema num verso não demonstra que nunca aparece no autor. A comparação precisa de limites."],"_l":"m6-f09"},{"t":"vf","p":"Encontrar hipérbole num poema de Cesário demonstra que Antero não pode usar esse recurso.","v":false,"f":"Falso: identificar um recurso num texto não o reserva ao autor. Compara o que o procedimento faz em cada passagem, sem inventar exclusividades.","_l":"m6-f09"},{"t":"escolha","p":"Que contraste podes fundamentar nestes dois recortes?","o":["O conforto da casa apalaçada e a precariedade da vendedora","A noite fria na cidade e a manhã luminosa no campo","O desemprego do sujeito e a pobreza da vendedora que encontra","A tristeza do sujeito e a alegria da vendedora na escada"],"c":0,"f":"A casa é «apalaçada»; a rapariga surge «rota» e ajoelha-se com o cesto. O contraste social assenta nestas escolhas concretas. O texto situa-se de manhã e o sujeito vai trabalhar: as outras opções acrescentam ou contradizem informação.","_l":"m6-f12","fe":[null,"O primeiro verso marca a hora, «Dez horas da manhã»; e tudo se passa na «larga rua macadamisada», na cidade.","O sujeito não está desempregado: entre os recortes diz que desce para o emprego; o contraste está entre a casa «apalaçada» e a rapariga «rota».","Nada nos versos fala de alegria ou de tristeza; o que se opõe são a casa «apalaçada» e a rapariga «rota, pequenina»."]},{"t":"escolha","p":"Um colega escreve: «A rapariga é pobre, logo o sujeito descreve-a sem escolher palavras.» Como corriges a inferência?","o":["A pobreza da rapariga prova que nenhuma palavra do retrato foi escolhida","«Rota», «pequenina» e «azafamada» mostram um olhar que seleciona traços","Só há escolha de palavras nos poemas de amor, não nos que descrevem a rua","Uma descrição da rua não pode ter ponto de vista: só regista o que lá está"],"c":1,"f":"Uma condição social não torna a descrição neutra. Os três qualificativos selecionam o que o leitor vê. Isto permite analisar o ponto de vista sem confundir o sujeito do poema com uma câmara imparcial.","_l":"m6-f12","fe":["A condição de quem é descrito não decide nada sobre as palavras: «rota», «pequenina» e «azafamada» foram escolhidas entre muitas possíveis.",null,"Cesário escolhe palavras ao descrever a rua: a rapariga é «rota, pequenina, azafamada» e o cesto é «Como um retalho de horta agglomerada».","Toda a descrição escolhe: «Notei de costas uma rapariga» já diz de onde o sujeito olha e o que repara nela."]},{"t":"vf","p":"Antes de reler. Recupera a leitura de Cesário na F12: os pormenores sensoriais podem coexistir com avaliações da voz que observa?","v":true,"f":"Confundir observação concreta e neutralidade apaga a seleção poética. Relê uma imagem da F12 e distingue o pormenor observado da relação que a voz constrói.","_l":"m6-f15"},{"t":"escolha","p":"Que leitura articula sensação e trabalho?","o":["A luz e as posturas tornam o esforço visível.","A luz e as posturas tornam o esforço agradável.","A luz e as posturas exprimem a voz dos operários."],"c":0,"f":"A claridade acompanha corpos e ações. O poema não nos dá, por isso, acesso automático ao pensamento de cada trabalhador.","fe":["A claridade acompanha corpos e ações. O poema não nos dá, por isso, acesso automático ao pensamento de cada trabalhador.","Transformas a intensidade da sensação em agrado dos trabalhadores. Relê as posturas e o peso que as imagens tornam visíveis.","Atribuis aos operários a voz que os observa. Regressa à distinção entre pormenor visto e palavras ditas pelas personagens."],"_l":"m6-f15"}],"licoes":["m6-f07","m6-f05","m6-f08","m6-f12","m6-f15","m6-f09"]}],M="M6",TIT="Poesia Realista",$=function(s,r){return (r||document).querySelector(s)},$$=function(s,r){return Array.prototype.slice.call((r||document).querySelectorAll(s))};window.EPIUnitTaskRoute.mount({units:U,module:M,title:TIT,tasks:[{"number": 1, "title": "Um ideal que não se alcança", "href": "../tarefas/m6-u1/"}, {"number": 2, "title": "A cidade vista e transfigurada", "href": "../tarefas/m6-u2/"}]});
})();
